import {bracketLayout} from './bracket-layout.js';
import ExcelJS from 'exceljs';
import {courtRows,label,leagueForm} from './tournament-forms.js';
import type {Tournament} from './model.js';

export async function formsWorkbook(t:Tournament) {
  const book=new ExcelJS.Workbook();
  const entries=new Map(t.events.flatMap(e=>e.entries).map(e=>[e.id,e]));
  const sheet=(name:string,landscape=true)=>{
    const ws=book.addWorksheet(name,{pageSetup:{paperSize:(landscape?8:9) as ExcelJS.PaperSize,orientation:landscape?'landscape':'portrait',
      fitToPage:true,fitToWidth:1,fitToHeight:0,margins:{left:.25,right:.25,top:.4,bottom:.4,header:.15,footer:.15}}});
    ws.addRow([t.name+'　'+name]);ws.getRow(1).font={bold:true,size:14};
    return ws;
  };
  const grid=(ws:ExcelJS.Worksheet,values:ExcelJS.CellValue[])=>{
    const row=ws.addRow(values);row.height=Math.max(22,...values.map(v=>String(v??'').split('\n').length*15));
    values.forEach((_,i)=>{
      const c=row.getCell(i+1);c.alignment={wrapText:true,vertical:'middle',horizontal:i?'center':'left'};
      const edge={style:'thin' as const,color:{argb:'FFB8C1CC'}};
      c.border={top:edge,left:edge,bottom:edge,right:edge};
      ws.getColumn(i+1).width=i?13:27;
      if(row.number===2)c.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFDDE7F5'}};
    });
  };
  let index=0;
  for(const s of t.stages)for(const g of s.groups){
    index++;
    const phase=s.source?'決勝':'予選', kind=s.kind==='league'?'リーグ':'トーナメント';
    for(const results of [false,true]){
      const ws=sheet(index+' '+(results?kind+'結果':phase+kind+'組合せ'));
      ws.getCell('A1').value=t.name+'　'+g.name;
      if(s.kind==='league'){
        const form=leagueForm(t,g.id);
        grid(ws,results?form.headers:form.headers.slice(0,g.entries.length+1));
        for(const r of form.rows) grid(ws,[r.name,...r.cells.map(c=>[c.match?label(c.match):'',results?c.text:''].filter(Boolean).join('\n')),...(results?r.stats:[])]);
        ws.pageSetup.printTitlesRow='1:2';
        for(let r=37;r<=ws.rowCount;r+=35)ws.getRow(r).addPageBreak();
      }else{
        ws.views=[{showGridLines:false}];
        if(g.entries.length<=64)ws.pageSetup.fitToHeight=1;
        const layout=bracketLayout(t,t.matches.filter(m=>m.groupId===g.id),results);
        const col=(x:number)=>Math.round(x/20)+2,row=(y:number)=>Math.round(y/12)+4;
        for(const p of [...layout.segments].sort((a,b)=>Number(a.red)-Number(b.red))){
          const border={style:p.red?'medium' as const:'thin' as const,color:{argb:p.red?'FFC31329':'FF000000'}};
          if(p.y1===p.y2){
            for(let c=Math.min(col(p.x1),col(p.x2))+1;c<=Math.max(col(p.x1),col(p.x2));c++){
              const cell=ws.getCell(row(p.y1),c);cell.border={...cell.border,bottom:border};
            }
          }else{
            for(let r=Math.min(row(p.y1),row(p.y2))+1;r<=Math.max(row(p.y1),row(p.y2));r++){
              const cell=ws.getCell(r,col(p.x1));cell.border={...cell.border,right:border};
            }
          }
        }
        for(const p of layout.captions){
          const x=col(p.x),y=row(p.y),player=p.kind==='player';
          const column=p.align==='start'?x+1:x;
          for(const [i,value] of p.lines.entries()){
            const rr=y+i+(p.kind==='number'||p.kind==='score'?1:0);
            // Leave borders intact. Alignment uses adjacent blank editable cells.
            const cell=ws.getCell(rr,column);
            cell.value=value;cell.alignment={horizontal:p.align==='end'?'right':p.align==='middle'?'center':'left'};
            cell.font={size:player?10:9,color:{argb:p.kind==='number'?'FF777777':'FF000000'}};
          }
        }
        for(let c=1;c<=ws.columnCount;c++)ws.getColumn(c).width=3;
        for(let r=2;r<=ws.rowCount;r++)ws.getRow(r).height=11;
        if(g.entries.length>64)for(let r=59;r<=ws.rowCount;r+=56)ws.getRow(r).addPageBreak();
      }
      ws.pageSetup.printArea='A1:'+ws.getCell(ws.rowCount,ws.columnCount).address;
    }
  }
  const ws=sheet('コート別タイムテーブル',t.courts>8);
  grid(ws,['順',...Array.from({length:t.courts},(_,i)=>(i+1)+'コート')]);
  const colors=['FFE4F2FF','FFFFEACC','FFE4F4DF','FFF4E2F9','FFFFE2E7','FFE1F5F3'];
  const eventOrder=new Map(t.events.map((e,i)=>[e.id,i]));
  courtRows(t).forEach((r,i)=>{
    grid(ws,[i+1,...r.map(m=>m?label(m):'')]);
    r.forEach((m,j)=>{if(m)ws.getCell(i+3,j+2).fill={type:'pattern',pattern:'solid',fgColor:{argb:colors[(eventOrder.get(m.eventId)||0)%colors.length]}};});
  });
  ws.pageSetup.printTitlesRow='1:2';ws.pageSetup.printArea='A1:'+ws.getCell(ws.rowCount,ws.columnCount).address;
  if(index===0)ws.addRow(['組合せ・コート割当後に試合が表示されます。']);
  return book;
}
