import {migratePractices} from './gas-practice-migration.js';
import {migrateTeams,migrateMasterRows} from './gas-team-migration.js';
import type {TeamMigrationOptions} from './gas-team-migration.js';
import {create,ensure,validate,uid} from './model.js';import type {Tournament,Match,Game,Rule} from './model.js';import {standings} from './engine.js';
type Row=Record<string,unknown>;type Tables=Record<string,unknown[][]>;
export function migrateGas(input:unknown,options:TeamMigrationOptions&{practiceRules?:Record<string,Rule>}={}){const source=input as {format?:string;state?:{sheets?:Tables;properties?:Record<string,unknown>;progress?:Record<string,{status:string;courtId?:string}>}};ensure(source?.format==='badminton-v3-gas-backup'&&source.state?.sheets,'対応形式はGAS v3 JSONバックアップです');const tables=source.state.sheets,properties=source.state.properties||{};const rows=(name:string):Row[]=>{const [head,...body]=tables[name]||[[]];ensure(Array.isArray(head)&&body.every(Array.isArray),'表形式不正：'+name);return body.map(r=>Object.fromEntries(head.map((key,i)=>[String(key),r[i]??''])));};const str=(r:Row,k:string)=>String(r[k]??''),num=(r:Row,k:string,fallback=0)=>Number(r[k]||fallback);const warnings:string[]=[],errors:string[]=[],tournaments:Tournament[]=[],counts:Record<string,unknown>[]=[];
 const known=new Set(['大会マスター','種目マスター','選手マスター','参加者一覧','ステージ','リーグ','リーグ参加者','試合一覧','得点記録','順位結果','操作履歴','大会選手','追加_ペア構成','追加_団体構成','追加_トーナメント','大会タイムテーブル','追加_団体試合','追加_団体内訳']);const retained=Object.entries(tables).filter(([k,v])=>!known.has(k)&&v.length>1).map(([table,data])=>({table,data}));for(const item of retained)warnings.push('未変換表を報告書に保持：'+item.table);
 const players=rows('選手マスター');for(const tour of rows('大会マスター')){try{const t=create(str(tour,'大会名'));const tid=str(tour,'大会ID');t.origin=tid;t.organizer=str(tour,'主催者');t.date=str(tour,'開催日').slice(0,10)||t.date;t.endDate=str(tour,'終了日').slice(0,10);t.venue=str(tour,'会場');t.category=str(tour,'大会区分');t.state=str(tour,'大会状態');const settings=properties['v3settings_'+tid] as {courts?:number;restMs?:number}|undefined;t.courts=settings?.courts||8;t.restMinutes=(settings?.restMs||0)/60000;
 const es=rows('種目マスター').filter(e=>str(e,'大会ID')===tid);for(const raw of es){const eid=str(raw,'種目ID');const rule=(properties['v305_event_rule_'+eid] as {base:number;cap:number;wins:number;deuce:boolean})||{base:num(tour,'得点基本点',21),cap:num(tour,'得点上限',30),wins:num(tour,'必要ゲーム勝数',2),deuce:str(tour,'デュース方式')!=='なし'};const type=str(raw,'競技種別')==='団体戦'?'team':str(raw,'競技種別')==='ダブルス'?'doubles':'singles';const entries=rows('参加者一覧').filter(p=>str(p,'種目ID')===eid).map(p=>{const id=str(p,'参加ID'),master=players.find(x=>str(x,'選手ID')===str(p,'登録ID'));const members=[...rows('追加_ペア構成'),...rows('追加_団体構成')].filter(x=>str(x,'参加ID')===id).sort((a,b)=>num(a,'順番')-num(b,'順番')).map(x=>str(x,'選手ID'));return {id,name:str(p,'表示名'),club:str(p,'所属クラブ'),seed:num(p,'シード順位'),players:members.length?members:[str(p,'登録ID')||id],kana:master?str(master,'フリガナ'):'',gender:master?str(master,'性別'):'',grade:master?str(master,'学年'):'',status:str(p,'参加状態')};});t.events.push({id:eid,name:str(raw,'種目名'),type,rule,entries});}
 const stageRows=rows('ステージ').filter(s=>str(s,'大会ID')===tid).sort((a,b)=>num(a,'ステージ順')-num(b,'ステージ順'));for(const r of stageRows){const id=str(r,'ステージID'),brackets=rows('追加_トーナメント').filter(x=>str(x,'ステージID')===id);const groups=rows('リーグ').filter(g=>str(g,'ステージID')===id).map(g=>({id:str(g,'リーグID'),name:str(g,'リーグ名'),entries:rows('リーグ参加者').filter(p=>str(p,'リーグID')===str(g,'リーグID')).sort((a,b)=>num(a,'リーグ内順番')-num(b,'リーグ内順番')).map(p=>str(p,'参加ID'))}));if(brackets.length)groups.push({id:uid(),name:str(r,'ステージ名'),entries:[...new Set(brackets.flatMap(b=>[str(b,'左参加ID'),str(b,'右参加ID')]).filter(Boolean))]});t.stages.push({id,eventId:str(r,'種目ID'),name:str(r,'ステージ名'),kind:brackets.length?'bracket':'league',source:str(r,'進出元ステージID')||undefined,groups});}
 const scoreRows=rows('得点記録');const timetable=rows('大会タイムテーブル').filter(x=>str(x,'大会ID')===tid);let number=0;const status=(s:string):Match['status']=>s==='終了'?'completed':s==='不戦勝'?'bye':'waiting';const gs=(r:Row):Game[]=>{const raw=JSON.parse(str(r,'得点JSON')||'[]') as {left:number;right:number}[];return raw.map(g=>[Number(g.left),Number(g.right)]);};
 const append=(r:Row,bracket:boolean)=>{const sid=str(r,'ステージID'),s=t.stages.find(s=>s.id===sid);if(!s)return;const id=str(r,bracket?'対戦ID':'試合ID'),at=timetable.find(x=>str(x,'試合ID')===id);const time=(str(at||{},'予定開始')||'00:00').split(':').map(Number);const m:Match={id,stageId:sid,eventId:s.eventId,groupId:bracket?s.groups.at(-1)!.id:str(r,'リーグID'),number:++number,round:bracket?num(r,'ラウンド',1):1,left:str(r,bracket?'左参加ID':'左側参加ID'),right:str(r,bracket?'右参加ID':'右側参加ID'),deps:[],games:bracket?gs(r):scoreRows.filter(g=>str(g,'試合ID')===id).sort((a,b)=>num(a,'ゲーム番号')-num(b,'ゲーム番号')).map(g=>[num(g,'左側得点'),num(g,'右側得点')]),winner:str(r,'勝者参加ID'),status:status(str(r,'試合状態')),court:num(at||{},'コート'),time:time[0]*60+time[1],duration:num(at||{},'予定時間分',20)};if(m.winner&&!m.games.length&&m.status!=='bye'){m.walkover=true;m.status='completed';t.history.push({at:new Date().toISOString(),op:uid(),action:'walkover:'+id,revision:0});}t.matches.push(m);};rows('試合一覧').filter(m=>str(m,'大会ID')===tid).forEach(r=>append(r,false));const bs=rows('追加_トーナメント').filter(b=>t.stages.some(s=>s.id===str(b,'ステージID'))).sort((a,b)=>num(a,'ラウンド')-num(b,'ラウンド')||num(a,'位置')-num(b,'位置'));bs.forEach(r=>append(r,true));for(const b of bs.filter(b=>num(b,'ラウンド')>1)){const m=t.matches.find(m=>m.id===str(b,'対戦ID'))!;m.deps=[0,1].map(i=>{const child=bs.find(c=>str(c,'ステージID')===m.stageId&&num(c,'ラウンド')===m.round-1&&num(c,'位置')===num(b,'位置')*2+i);ensure(child,'欠損トーナメント依存');return str(child,'対戦ID');});}
 const teams=migrateTeams(t,rows,options);warnings.push(...teams.warnings);
 for(const r of rows('順位結果')){const group=t.stages.flatMap(s=>s.groups).find(g=>g.id===str(r,'リーグID'));if(!group)continue;const actual=standings(t,group.id).find(a=>a.id===str(r,'参加ID'));if(actual&&actual.rank!==num(r,'順位'))warnings.push(t.name+' / '+group.name+'：保存順位と再計算順位に差があります（同率裁定含む）');}
 validate(t);counts.push({tournamentId:t.id,sourceId:tid,tournament:t.name,events:es.length,entries:t.events.reduce((n,e)=>n+e.entries.length,0),matches:t.matches.length,completed:t.matches.filter(m=>m.status==='completed').length,sourceMatches:rows('試合一覧').filter(m=>str(m,'大会ID')===tid).length+bs.length,sourceTeamFixtures:teams.sourceFixtures,convertedTeamFixtures:teams.convertedFixtures,teamAliases:teams.aliases});tournaments.push(t);
 }catch(e){errors.push(str(tour,'大会名')+'：'+String(e));}}
 const practiceMigration=migratePractices(rows,tournaments,options.practiceRules);warnings.push(...practiceMigration.warnings);errors.push(...practiceMigration.errors);for(const table of ['練習メンバー','練習セッション','練習試合'])if(retained.some(r=>r.table===table)&&!practiceMigration.errors.length){const at=warnings.indexOf('未変換表を報告書に保持：'+table);if(at>=0)warnings[at]='変換済み練習原表を報告書に保持：'+table;}
 for(const t of tournaments){let item=counts.find(c=>c.tournamentId===t.id);if(!item){item={tournamentId:t.id,sourceId:t.origin,tournament:t.name,events:0,entries:0,matches:0,completed:0,sourceMatches:0};counts.push(item);}item.practiceSessions=t.practice?.length||0;item.practiceMatches=t.practice?.reduce((n,p)=>n+p.matches.length,0)||0;}
 ensure(tournaments.length||errors.length,'大会データなし');let masters:ReturnType<typeof migrateMasterRows>={records:[],warnings:[]};try{masters=migrateMasterRows(rows,tournaments);warnings.push(...masters.warnings);}catch(e){errors.push('共通マスター：'+String(e));}return {format:'gas-to-offline-report-v1',tournaments,counts,warnings,errors,retained,practiceMigration,masterRecords:masters.records,sourcePlayers:players,sourceBackup:input};}
