import {bracketLayout} from './bracket-layout.js';
import {matchNumber} from './model.js';
import {ensure, finished} from './model.js';
import type {Match, Stage, Tournament} from './model.js';
import {standings} from './engine.js';
import {leagueCrossTable, escapeHtml as esc} from './reports.js';

export const label = (m: Match) => String(matchNumber(m));
export const stateClass = (m: Match) => finished(m) ? 'done' :
  m.status === 'called' || m.status === 'playing' ? 'called' : 'waiting';

export function assignLabels(t: Tournament, eventId: string, code: string) {
  ensure(/^[A-Za-z0-9]{1,12}$/.test(code), '種目コードは英数字1〜12文字');
  const active = t.matches.filter(m => m.eventId === eventId && m.status !== 'bye');
  ensure(active.every(m => m.status === 'waiting' && !m.startedAt && !m.rubbers?.some(r => r.games.length)), '進行開始後は再採番できません');
  const ordered = t.stages.filter(s => s.eventId === eventId).flatMap(s =>
    s.kind==='bracket'?active.filter(m=>m.stageId===s.id).sort((a,b)=>a.round-b.round||a.number-b.number):s.groups.flatMap(g=>active.filter(m=>m.groupId===g.id).sort((a,b)=>a.number-b.number)));
  const other = new Set(t.matches.filter(m => m.eventId !== eventId).map(label));
  ensure(ordered.every((_,i) => !other.has(code+'-'+(i+1))), '別種目と試合番号が重複します');
  ordered.forEach((m,i) => {m.displayNumber=code+'-'+(i+1);});
}

export function leagueForm(t: Tournament, gid: string) {
  const group = t.stages.flatMap(s => s.groups).find(g => g.id === gid)!;
  const matches=t.matches.filter(m=>m.groupId===gid);
  const cross=leagueCrossTable(t,gid), ranks=new Map(standings(t,gid).map(r=>[r.id,r]));
  const entries=new Map(t.events.flatMap(e=>e.entries).map(e=>[e.id,e]));
  const pair=(a:string,b:string)=>[a,b].sort().join('|');
  const fixtures=new Map(matches.map(m=>[pair(m.left,m.right),m]));
  const complete=matches.length===group.entries.length*(group.entries.length-1)/2&&matches.every(finished);
  return {
    headers:['選手・所属',...group.entries.map(id=>entries.get(id)?.name||id),'勝','敗','勝率','得G','失G','差G','得点','失点','点差','順位'],
    rows:group.entries.map((id,i)=>{
      const e=entries.get(id)!, r=ranks.get(id)!;
      return {
        name:[e.name,e.club].filter(Boolean).join('\n'),
        cells:group.entries.map((other,j)=>({match:fixtures.get(pair(id,other)),text:cross.rows[i][j+1]})),
        stats:[r.wins,r.losses,(100*r.rate).toFixed(1)+'%',r.gf,r.ga,r.gd,r.pf,r.pa,r.pd,(complete&&!r.tied?'確定 ':complete?'同順位 ':'暫定 ')+r.rank]
      };
    })
  };
}

const clock=(m:number)=>String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');
export function courtRows(t: Tournament) {
  const columns=Array.from({length:t.courts},(_,i)=>t.matches.filter(m=>m.court===i+1&&m.status!=='bye')
    .sort((a,b)=>a.time-b.time||(a.queueOrder??a.number)-(b.queueOrder??b.number)));
  return Array.from({length:Math.max(0,...columns.map(c=>c.length))},(_,i)=>columns.map(c=>c[i]));
}
export function timetable(t:Tournament,progress:boolean,limit=Infinity) {
  const codes=new Map(t.events.map((e,i)=>[e.id,i%6]));
  const rows=courtRows(t);
  return '<div class="table compact-courts" tabindex="0"><table><thead><tr><th>順</th>'+Array.from({length:t.courts},(_,i)=>'<th>'+(i+1)+'コート</th>').join('')+'</tr></thead><tbody>'+
    rows.slice(0,limit).map((row,i)=>'<tr><th>'+(i+1)+'</th>'+row.map(m=>m
      ? '<td class="event-tint-'+codes.get(m.eventId)+(progress?' '+stateClass(m):'')+'"><button data-act="matchEdit" data-id="'+esc(m.id)+'" title="'+esc(clock(m.time)+' '+m.status)+'">'+esc(label(m))+'</button></td>'
      : '<td></td>').join('')+'</tr>').join('')+'</tbody></table></div>';
}
const button=(m:Match,content:string)=>'<button class="match-link '+stateClass(m)+'" data-act="formScore" data-id="'+esc(m.id)+'">'+content+'</button>';
export function leagueTable(t:Tournament,gid:string){
  const form=leagueForm(t,gid);
  return '<div class="table"><table class="league-form"><thead><tr>'+form.headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+
    form.rows.map(r=>'<tr><th>'+esc(r.name)+'</th>'+r.cells.map(c=>'<td>'+(c.match?button(c.match,esc(label(c.match))):'')+
      '<div>'+esc(c.text)+'</div></td>').join('')+r.stats.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
}

export type Branch={match:Match; side:number; x:number; y:number; top:number; bottom:number; stem:number};
export function bracketGeometry(matches:Match[]) {
  const byId=new Map(matches.map(m=>[m.id,m]));
  const children=new Set(matches.flatMap(m=>m.deps));
  const root=matches.find(m=>!children.has(m.id));
  if(!root)return {nodes:[] as Branch[],height:150,width:680};
  const width=440+320*root.round, center=width/2, nodes:Branch[]=[];
  const height=Math.max(210,2**Math.max(0,root.round-2)*168);
  function place(m:Match,side:number,lo:number,hi:number) {
    const y=(lo+hi)/2, x=center+side*(root!.round-m.round)*160;
    const top=lo+(hi-lo)/4,bottom=hi-(hi-lo)/4;
    nodes.push({match:m,side,x,y,top,bottom,stem:x+side*135});
    m.deps.forEach((id,i)=>{
      const child=byId.get(id);
      if(child) place(child,side|| (i===0?-1:1),side===0?0:i===0?lo:y,side===0?height:i===0?y:hi);
    });
  }
  place(root,0,0,height);
  return {nodes,height,width};
}

export function gameLines(m:Match){
  if(m.walkover)return ['不戦勝'];
  if(m.rubbers?.length)return m.rubbers.map((r,i)=> (i+1)+'本 '+r.games.map(g=>g.join('-')).join(' / '));
  return m.games.map(g=>g.join('-'));
}
export function bracketTable(t:Tournament,matches:Match[]){
  const {width,height,segments,captions}=bracketLayout(t,matches);
  const paths=[...segments].sort((a,b)=>Number(a.red)-Number(b.red)).map(p=>
    '<path class="'+(p.red?'win-path':'normal-path')+'" d="M '+p.x1+' '+p.y1+' L '+p.x2+' '+p.y2+'"/>').join('');
  const text=captions.map(c=>{
    const body=c.lines.map(esc).join('<br>');
    const content=c.match?'<button type="button" data-act="formScore" data-id="'+esc(c.match.id)+
      '" aria-label="試合 '+esc(matchNumber(c.match))+' の得点入力・訂正">'+body+'</button>':body;
    return '<div class="paper-caption paper-'+c.kind+' paper-align-'+c.align+'" style="left:'+c.x+'px;top:'+c.y+'px">'+content+'</div>';
  }).join('');
  return '<div class="table bracket-pan" tabindex="0" aria-label="トーナメント表。横スクロールできます"><div class="bracket-canvas" style="width:'+width+'px;height:'+height+'px"><svg aria-hidden="true" width="'+width+'" height="'+height+'">'+paths+'</svg>'+text+'</div></div>';
}
export function stageForms(t:Tournament,stages:Stage[],limit=Infinity){
  return stages.flatMap(s=>s.groups.map((g,i)=>({s,g,i}))).slice(0,limit).map(({s,g,i})=>'<details class="form-block"'+(i===0?' open':'')+'><summary>'+esc(g.name)+'</summary>'+
    (s.kind==='league'?leagueTable(t,g.id):bracketTable(t,t.matches.filter(m=>m.groupId===g.id)))+'</details>').join('');
}
