import type {Tournament} from './model.js';
export function rankingSignature(t:Tournament,gid:string,rows:{id:string;played:number;wins:number;rate:number;gd:number;pd:number;rd:number}[]){const stage=t.stages.find(s=>s.groups.some(g=>g.id===gid)),group=stage?.groups.find(g=>g.id===gid);const ids=new Set(group?.entries||[]);return JSON.stringify({stats:rows.map(({id,played,wins,rate,gd,pd,rd})=>({id,played,wins,rate,gd,pd,rd})).sort((a,b)=>a.id.localeCompare(b.id)),matches:t.matches.filter(m=>(m.groupId===gid||m.stageId===stage?.source)&&ids.has(m.left)&&ids.has(m.right)).map(m=>({id:m.id,left:m.left,right:m.right,status:m.status,winner:m.winner,games:m.games,rubbers:m.rubbers})).sort((a,b)=>a.id.localeCompare(b.id))});}
