import {create,ensure,result,ruleCheck,uid,validate} from './model.js';
import type {Rule,Tournament} from './model.js';
import type {Practice} from './practice.js';
import type {GasRows} from './gas-team-migration.js';
const text=(r:Record<string,unknown>,key:string)=>String(r[key]??'');
export function practiceMasterId(id:string){ensure(/^[\w-]{1,80}$/.test(id)&&!['__proto__','constructor','prototype'].includes(id),'練習メンバーIDが不正：'+id);return 'practice-'+id;}
export function migratePractices(rows:GasRows,tournaments:Tournament[],rules:Record<string,Rule>={}){
 const sourceMembers=rows('練習メンバー'),sessions=rows('練習セッション'),games=rows('練習試合');
 const warnings:string[]=[],errors:string[]=[],aliases:{sessionId:string;sourceId:string;memberId:string;masterId:string}[]=[],sessionIds=new Set<string>(),memberIds=new Set<string>(),gameIds=new Set<string>();let converted=0,convertedMatches=0,completed=0;
 try{
  for(const m of sourceMembers){const id=text(m,'メンバーID');practiceMasterId(id);ensure(!memberIds.has(id),'練習メンバーID重複：'+id);memberIds.add(id);ensure(text(m,'氏名').trim()&&text(m,'氏名').length<=120,'練習者名が不正：'+id);}
  for(const s of sessions){const id=text(s,'セッションID');ensure(/^[\w-]{1,100}$/.test(id)&&!sessionIds.has(id),'練習セッションIDが不正または重複：'+id);sessionIds.add(id);}
  for(const g of games){const id=text(g,'試合ID');ensure(/^[\w-]{1,100}$/.test(id)&&!gameIds.has(id),'練習試合IDが不正または重複：'+id);gameIds.add(id);ensure(sessionIds.has(text(g,'セッションID')),'練習試合のセッション参照が不正：'+id);}
 }catch(e){errors.push('練習履歴：'+String(e));return {warnings,errors,aliases,sessions:0,matches:0,completed:0,sourceSessions:sessions.length,sourceMatches:games.length};}
 for(const s of sessions){const sid=text(s,'セッションID');try{
  const parsed=JSON.parse(text(s,'参加ID一覧')||'[]') as unknown;ensure(Array.isArray(parsed)&&parsed.length>=4&&parsed.length<=200&&parsed.every(id=>typeof id==='string'&&memberIds.has(id))&&new Set(parsed).size===parsed.length,'参加ID一覧が不正：'+sid);const ids=parsed as string[];
  const courts=Number(s['コート数']),rounds=Number(s['巡数']);ensure(Number.isInteger(courts)&&courts>=1&&courts<=64&&Number.isInteger(rounds)&&rounds>=1&&rounds<=50,'練習コート数/巡数が不正：'+sid);
  const rule=structuredClone(rules[sid]||{base:21,cap:30,wins:1,deuce:true});ruleCheck(rule);ensure(rule.wins===1,'GAS練習履歴は1ゲーム方式です：'+sid);
  const mapping=new Map(ids.map(id=>[id,uid()])),sessionAliases=ids.map(id=>({sessionId:sid,sourceId:id,memberId:mapping.get(id)!,masterId:practiceMasterId(id)}));
  const members=ids.map(id=>({id:mapping.get(id)!,name:text(sourceMembers.find(m=>text(m,'メンバーID')===id)!,'氏名'),masterId:practiceMasterId(id)}));
  const sourceGames=games.filter(g=>text(g,'セッションID')===sid);ensure(sourceGames.length<=2500&&sourceGames.length===Math.min(courts,Math.floor(ids.length/4))*rounds,'練習試合数とコート数/巡数が不一致：'+sid);
  const matches=sourceGames.map(g=>{const id=text(g,'試合ID'),round=Number(g['巡']),court=Number(g['コート']);ensure(Number.isInteger(round)&&round>=1&&round<=rounds&&Number.isInteger(court)&&court>=1&&court<=courts,'練習試合の巡/コートが不正：'+id);const sourceLeft=[text(g,'左1'),text(g,'左2')],sourceRight=[text(g,'右1'),text(g,'右2')],all=[...sourceLeft,...sourceRight];ensure(all.every(x=>mapping.has(x))&&new Set(all).size===4,'練習試合の参照/選手重複：'+id);const left=sourceLeft.map(x=>mapping.get(x)!),right=sourceRight.map(x=>mapping.get(x)!);const status=text(g,'状態');ensure(['終了','未入力','未開始',''].includes(status),'未対応の練習状態：'+id);let scores:[number,number][]=[];let winner='';if(status==='終了'){ensure(text(g,'左得点').trim()!==''&&text(g,'右得点').trim()!=='','終了練習に得点なし：'+id);scores=[[Number(g['左得点']),Number(g['右得点'])]];winner=result(scores,rule);}else ensure(text(g,'左得点')===''&&text(g,'右得点')==='','未終了練習に途中得点があります。元記録を確認：'+id);return {id,round,court,left,right,games:scores,winner};});
  const used=new Set<string>();for(const m of matches){const key=m.round+':'+m.court;ensure(!used.has(key),'練習の同一巡/コート重複：'+sid);used.add(key);}
  const name=text(s,'名称');ensure(name.trim()&&name.length<=120,'練習名が不正：'+sid);const practice:Practice={id:sid,name,members,rule,matches};
  const tid=text(s,'大会ID');let host=tournaments.find(t=>t.origin===tid),separate=false;if(tid)ensure(host,'練習の大会ID参照が不正：'+sid);else{host=create(('練習履歴：'+name).slice(0,120));host.origin='gas-practice-'+sid;separate=true;const date=text(s,'作成日時').slice(0,10);ensure(/^\d{4}-\d{2}-\d{2}$/.test(date)&&Number.isFinite(Date.parse(date)),'共通練習の作成日が不正：'+sid);host.date=date;host.courts=courts;}
  ensure(host,'練習の移行先がありません');const copy=structuredClone(host);(copy.practice??=[]).push(practice);copy.history.push({at:new Date().toISOString(),op:uid(),action:'GAS練習移行：'+sid+' / 元作成日時 '+text(s,'作成日時'),revision:copy.revision});validate(copy);
  if(separate)tournaments.push(copy);else{host.practice=copy.practice;host.history=copy.history;}
  aliases.push(...sessionAliases);converted++;convertedMatches+=matches.length;completed+=matches.filter(m=>m.winner).length;
  warnings.push(sid+'：GAS練習には厳密な終了点ルールがないため、'+(rules[sid]?'明示指定ルール':'標準21点・上限30・1ゲーム')+'との一致を検査しました。'+(!tid?'大会IDのない共通練習は独立した練習履歴大会へ移しました。':''));
 }catch(e){errors.push('練習 '+sid+'：'+String(e));}}
 return {warnings,errors,aliases,sessions:converted,matches:convertedMatches,completed,sourceSessions:sessions.length,sourceMatches:games.length};
}
