import {matchNumber} from './model.js';
import type {Entry,Match,Tournament} from './model.js';

type Segment={x1:number;y1:number;x2:number;y2:number;red:boolean};
type Caption={x:number;y:number;align:'start'|'end'|'middle';kind:'player'|'count'|'number'|'score';lines:string[];match?:Match};
export function bracketLayout(t:Tournament,matches:Match[],results=true){
  const segments:Segment[]=[], captions:Caption[]=[];
  const index=new Map(matches.map(m=>[m.id,m]));
  const used=new Set(matches.flatMap(m=>m.deps));
  const final=matches.find(m=>!used.has(m.id));
  if(!final)return {width:680,height:100,segments,captions};
  const entries=new Map<string,Entry>(t.events.flatMap(e=>e.entries.map(p=>[p.id,p])));
  const step=120,edge=200,center=edge+step*final.round,w=2*center;
  const team=t.events.find(e=>e.id===final.eventId)?.team;
  const pitch=Math.max(64,(team?.rubbers??0)*16+16);
  function line(x1:number,y1:number,x2:number,y2:number,red=false){
    if(x1!==x2||y1!==y2)segments.push({x1,y1,x2,y2,red});
  }
  function players(m:Match):number{
    if(!m.deps.length)return Number(!!m.left)+Number(!!m.right);
    return m.deps.reduce((n,id)=>{const child=index.get(id);return n+(child?players(child):0);},0);
  }
  function player(id:string,side:number,y:number) {
    const entry=entries.get(id),x=side<0?edge:w-edge;
    if(entry)captions.push({x:x+side*10,y,align:side<0?'end':'start',kind:'player',
      lines:[entry.name,entry.club].filter(Boolean)});
    return {x,y,red:false};
  }
  function games(m:Match) {
    if(m.rubbers?.length)return m.rubbers.map((r,i)=>(i+1)+'本 '+r.games.map(g=>g.join('-')).join('/'));
    return m.games.map(g=>(m.winner===m.right?[g[1],g[0]]:g).join('-'));
  }
  function counts(m:Match){
    return [0,1].map(i=>{
      if(m.walkover)return m.winner===(i===0?m.left:m.right)?'':'×';
      return String(m.rubbers?.length?m.rubbers.filter(r=>r.winner===(i===0?'left':'right')).length:
        m.games.filter(g=>g[i]>g[1-i]).length);
    });
  }
  function caption(m:Match,x:number,y:number,side:number){
    const done=results&&m.status==='completed',score=done?games(m):[];
    if(done&&m.walkover)return;
    captions.push({x:x+side*9,y:y+(side===0?17:done?-8*Math.max(1,score.length):-8),align:side<0?'end':side>0?'start':'middle',
      kind:done?'score':'number',lines:done?(score.length?score:['結果を確認']):[String(matchNumber(m))],match:m});
  }
  function branch(m:Match,side:number,cursor:{y:number}):{x:number;y:number;red:boolean}{
    const leaf=(id:string)=>{const p=player(id,side,cursor.y);cursor.y+=pitch;return p;};
    if(m.status==='bye'&&!m.deps.length)return leaf(m.left||m.right);
    const [a,b]=m.deps.length?m.deps.map(id=>branch(index.get(id)!,side,cursor)):[leaf(m.left),leaf(m.right)];
    const x=center+side*step*(final!.round-m.round),y=(a.y+b.y)/2;
    const done=results&&m.status==='completed';
    [a,b].forEach((p,i)=>{
      const won=done&&!!m.winner&&m.winner===(i===0?m.left:m.right);
      line(p.x,p.y,x,p.y,p.red||won);
      line(x,p.y,x,y,won);
      if(done){
        const text=counts(m)[i];
        if(text)captions.push({x:x-side*6,y:p.y,align:side<0?'start':'end',kind:'count',lines:[text],match:m.walkover?m:undefined});
      }
    });
    caption(m,x,y,side);
    return {x,y,red:done&&!!m.winner};
  }
  const halves=final.deps.map(id=>index.get(id)!);
  let height=145;
  let left:{x:number;y:number;red:boolean},right:typeof left;
  if(halves.length===2){
    left=branch(halves[0],-1,{y:42});
    const rightSegments=segments.length,rightCaptions=captions.length;
    right=branch(halves[1],1,{y:42});
    const offset=left.y-right.y;
    // Align the semifinal outlets. Keep every participant on a uniformly spaced row within each half.
    const shift=(fromSegment:number,fromCaption:number,dy:number)=>{
      for(let i=fromSegment;i<segments.length;i++){segments[i].y1+=dy;segments[i].y2+=dy;}
      for(let i=fromCaption;i<captions.length;i++)captions[i].y+=dy;
    };
    if(offset>=0){shift(rightSegments,rightCaptions,offset);right.y+=offset;}
    else{shift(0,0,-offset);shift(rightSegments,rightCaptions,offset);left.y-=offset;}
    height=Math.max(players(halves[0])*pitch+Math.max(0,-offset),players(halves[1])*pitch+Math.max(0,offset))+60;
  }else{
    left=player(final.left,-1,65);right=player(final.right,1,65);
  }
  const y=(left.y+right.y)/2,finished=results&&final.status==='completed';
  [left,right].forEach((p,i)=>{
    const won=finished&&!!final.winner&&final.winner===(i===0?final.left:final.right);
    line(p.x,p.y,center,p.y,p.red||won);line(center,p.y,center,y,won);
    const count=finished?counts(final)[i]:'';
    if(count)captions.push({x:center+(i===0?-1:1)*20,y:p.y-10,align:'middle',kind:'count',lines:[count],match:final.walkover?final:undefined});
  });
  line(center,y,center,y-35,finished&&!!final.winner);
  caption(final,center,y,0);
  return {width:w,height,segments,captions};
}
