const sensitive=/(password|passphrase|token|secret|credential|authorization|cookie)/i;
export function scrubDiagnostic(value:unknown,depth=0):unknown{if(depth>12)return '[depth limit]';if(typeof value==='string')return value.slice(0,4000).replace(/((?:password|passphrase|token|secret|authorization)\s*[:=]\s*)[^\s,;]+/gi,'$1[redacted]');if(Array.isArray(value))return value.slice(0,500).map(v=>scrubDiagnostic(v,depth+1));if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([k,v])=>[k,sensitive.test(k)?'[redacted]':scrubDiagnostic(v,depth+1)]));return value;}
export function buildDiagnostic(logs:unknown[],detail?:{drafts:unknown[];pending:unknown}){return {version:'1.0.0-rc.4',at:new Date().toISOString(),detailIncluded:!!detail,logs:scrubDiagnostic(logs),...(detail?{drafts:scrubDiagnostic(detail.drafts),pending:scrubDiagnostic(detail.pending)}:{})};}
