import {scrubDiagnostic} from './diagnostics.js';
import {ensure,validate,uid,repairProgressMetadata} from './model.js';
import type {Tournament} from './model.js';
export type Envelope={id:string;revision:number;json:string;hash:string};
export async function hash(value:string){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value))),b=>b.toString(16).padStart(2,'0')).join('');}
const req=<T>(r:IDBRequest<T>)=>new Promise<T>((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
export const done=(tx:IDBTransaction)=>new Promise<void>((resolve,reject)=>{tx.oncomplete=()=>resolve();tx.onabort=()=>reject(tx.error||Error('保存中断'));tx.onerror=()=>{};});
export class Store {
 db:IDBDatabase;
 constructor(db:IDBDatabase){this.db=db;}
 static async open(name='badminton-offline-rc61'){
 const r=indexedDB.open(name,2);let upgradeFailure:unknown;
 r.onupgradeneeded=()=>{try{const db=r.result;for(const store of ['tournaments','snapshots','operations','drafts','logs','trash','pending','masters','templates'])if(!db.objectStoreNames.contains(store))db.createObjectStore(store,{keyPath:'id'});}catch(error){upgradeFailure=error;r.transaction?.abort();}};
 r.onblocked=()=>{if(typeof window!=='undefined')window.dispatchEvent(new CustomEvent('storage-blocked'));};
 let db:IDBDatabase;try{db=await req(r);}catch(error){throw upgradeFailure||error;}db.onversionchange=()=>db.close();return new Store(db);
 }
 async rows<T>(store:string){const tx=this.db.transaction(store),end=done(tx);const rows=await req(tx.objectStore(store).getAll());await end;return rows as T[];}
 async raw(id:string){const tx=this.db.transaction('tournaments'),end=done(tx);const r=await req(tx.objectStore('tournaments').get(id));await end;return r as Envelope|undefined;}
 async load(id:string){const r=await this.raw(id);ensure(r,'大会がありません');return this.decode(r);}
 async decode(r:Envelope){ensure(await hash(r.json)===r.hash,'破損検出：バックアップから別大会として復元してください');const parsed=JSON.parse(r.json) as Tournament;repairProgressMetadata(parsed);const t=validate(parsed);ensure(t.id===r.id&&t.revision===r.revision,'保存メタ情報不一致');return t;}
 async list(){const rows=await this.rows<Envelope>('tournaments');return Promise.all(rows.map(async r=>{try{const t=await this.decode(r);return {id:t.id,name:t.name,revision:t.revision,date:t.date,error:''};}catch(e){return {id:r.id,name:'破損した大会（削除せず保持）',revision:r.revision,date:'',error:String(e)};}}));}
 async save(input:Tournament,expected:number,op=uid(),action='保存'){
 const requestHash=await hash(JSON.stringify({input,expected,action}));
 const t=structuredClone(input);repairProgressMetadata(t);
 if(t.schema===1)for(const m of t.matches)if(m.status==='completed'&&m.walkover===undefined&&!m.games.length&&t.history.some(h=>h.action==='walkover:'+m.id))m.walkover=true;
 validate(t);ensure(t.revision===expected,'画面の更新番号が不一致');
 t.schema=2;t.featureVersion=2;t.revision=expected+1;t.updated=new Date().toISOString();t.history.push({at:t.updated,op,action,revision:t.revision});
 const json=JSON.stringify(t),digest=await hash(json),env={id:t.id,revision:t.revision,json,hash:digest};
 // No await/hash work inside an active Safari transaction.
 let tx:IDBTransaction;
 try{tx=this.db.transaction(['tournaments','snapshots','operations','trash'],'readwrite',{durability:'strict'});}
 catch{tx=this.db.transaction(['tournaments','snapshots','operations','trash'],'readwrite');}
 const end=done(tx),ts=tx.objectStore('tournaments'),ops=tx.objectStore('operations'),snaps=tx.objectStore('snapshots');
 let failure:Error|undefined,duplicate=false;
 const fail=(message:string)=>{failure=Error(message);tx.abort();};
 const guard=(fn:()=>void)=>()=>{try{fn();}catch(error){failure=error instanceof Error?error:Error(String(error));try{tx.abort();}catch{}}};
 const seen=ops.get(t.id+':'+op);
 seen.onsuccess=guard(()=>{
  if(seen.result){if(seen.result.requestHash!==requestHash)fail('操作IDが異なる内容で再利用されています');else duplicate=true;return;}
  const current=ts.get(t.id);
  current.onsuccess=guard(()=>{
   const old=current.result as Envelope|undefined;
   const apply=()=>{
    if((old?old.revision:0)!==expected){fail('更新競合：再読込してください。入力は下書きに保持しています');return;}
    if(old)snaps.put({...old,id:t.id+':'+old.revision,tournamentId:t.id,savedAt:Date.now()});
    ts.put(env);ops.put({id:t.id+':'+op,hash:digest,requestHash,revision:t.revision});
    const all=snaps.getAll();all.onsuccess=guard(()=>{const items=all.result.filter(x=>x.tournamentId===t.id).sort((a,b)=>b.revision-a.revision);items.slice(20).forEach(x=>snaps.delete(x.id));});
   };
   if(old)apply();else{const deleted=tx.objectStore('trash').get(t.id);deleted.onsuccess=guard(()=>{if(deleted.result)fail('削除済み大会への古い保存は拒否しました。別大会として復元してください');else apply();});}
  });
 });
 try{await end;}catch(error){throw failure||error;}
 return duplicate?await this.load(t.id):t;
 }
 async put(store:string,value:unknown){const tx=this.db.transaction(store,'readwrite'),end=done(tx);tx.objectStore(store).put(value);await end;}
 async removeDraft(id:string){const tx=this.db.transaction('drafts','readwrite'),end=done(tx);tx.objectStore('drafts').delete(id);await end;}
 async delete(id:string,expected:number){const tx=this.db.transaction(['tournaments','trash'],'readwrite'),end=done(tx);const r=tx.objectStore('tournaments').get(id);r.onsuccess=()=>{if(!r.result||r.result.revision!==expected){tx.abort();return;}tx.objectStore('trash').put({...r.result,deletedAt:Date.now()});tx.objectStore('tournaments').delete(id);};await end;}
 async restoreSnapshot(id:string){const rows=await this.rows<Envelope&{tournamentId:string}>('snapshots');const r=rows.find(x=>x.id===id);ensure(r,'世代がありません');ensure(await hash(r.json)===r.hash,'世代データ破損');return this.importCopy(validate(JSON.parse(r.json)));}
 async importCopy(t:Tournament){validate(t);const copy=structuredClone(t);copy.id=uid();copy.revision=0;if(copy.name.length<=116)copy.name+='（復元）';copy.history=structuredClone(t.history);return this.save(copy,0,uid(),'別大会として復元');}
 async importBundle(tours:Tournament[],masters:{id:string;kind:string;name:string}[]){
 ensure(tours.length>0&&tours.length<=100,'移行大会数が不正');ensure(new Set(masters.map(m=>m.id)).size===masters.length&&masters.every(m=>m.id&&m.name&&['player','club'].includes(m.kind)),'移行マスターが不正');
 const copies=tours.map(input=>{validate(input);const t=structuredClone(input);t.id=uid();if(t.name.length<=116)t.name+='（移行）';t.revision=1;t.updated=new Date().toISOString();t.history.push({at:t.updated,op:uid(),action:'GAS一括移行',revision:1});validate(t);return t;});
 const envelopes=await Promise.all(copies.map(async t=>{const json=JSON.stringify(t);return {id:t.id,revision:t.revision,json,hash:await hash(json)};}));
 const tx=this.db.transaction(['tournaments','masters'],'readwrite'),end=done(tx);let failure:Error|undefined;
 for(const m of masters){const store=tx.objectStore('masters'),r=store.get(m.id);r.onsuccess=()=>{if(r.result&&JSON.stringify(r.result)!==JSON.stringify(m)){failure=Error('既存マスターIDと内容が異なります：'+m.id);tx.abort();}else if(!r.result)store.add(m);};}
 for(const env of envelopes)tx.objectStore('tournaments').add(env);
 try{await end;}catch(e){throw failure||e;}return copies;
 }
 async insertMany(store:string,values:{id:string}[]){const tx=this.db.transaction(store,'readwrite'),end=done(tx);try{for(const v of values)tx.objectStore(store).add(v);}catch(e){tx.abort();await end.catch(()=>{});throw e;}await end;}
 async remove(store:string,id:string){const tx=this.db.transaction(store,'readwrite'),end=done(tx);tx.objectStore(store).delete(id);await end;}
 async queue(input:Tournament,expected:number,op:string,action:string,tab:string){validate(input);ensure(op&&op.length<=150&&input.revision===expected,'再試行操作ID・更新番号が不正');const signature=JSON.stringify({input,expected,action});const value={id:op,t:structuredClone(input),expected,op,action,tab,at:Date.now()};const tx=this.db.transaction('pending','readwrite'),end=done(tx);let failure:Error|undefined;const store=tx.objectStore('pending'),r=store.get(op);r.onsuccess=()=>{if(r.result){const p=r.result;if(JSON.stringify({input:p.t,expected:p.expected,action:p.action})!==signature){failure=Error('操作IDが異なる内容で再利用されています');tx.abort();}}else store.add(value);};try{await end;}catch(e){throw failure||e;}}

 async retryPending(op:string){const p=(await this.rows<{id:string;t:Tournament;expected:number;op:string;action:string}>('pending')).find(p=>p.id===op);ensure(p,'再試行要求なし');const t=await this.save(p.t,p.expected,p.op,p.action);await this.remove('pending',op);return t;}
 async pruneLogs(keep=500){const logs=await this.rows<{id:string;at:string}>('logs');const tx=this.db.transaction('logs','readwrite'),end=done(tx);logs.sort((a,b)=>b.at.localeCompare(a.at)).slice(keep).forEach(l=>tx.objectStore('logs').delete(l.id));await end;}
 async log(operation:string,error:unknown,phase='操作'){await this.put('logs',{id:uid(),at:new Date().toISOString(),operation,phase,type:error instanceof Error?error.name:'Error',message:scrubDiagnostic(String(error))});}
}
