export function repairProgressMetadata(t:Tournament){ensure(Array.isArray(t.matches),'試合形式が不正');for(const m of t.matches)if(m.finishedAt!==undefined)ensure(typeof m.finishedAt==='number'&&Number.isFinite(m.finishedAt)&&m.finishedAt>=0,'終了日時が不正');const affected=t.matches.filter(m=>m.finishedAt!==undefined&&m.status!=='completed'&&m.status!=='bye');for(const m of affected){delete m.finishedAt;t.history.push({at:new Date().toISOString(),op:uid(),action:'RC3 repair finishedAt:'+m.id,revision:t.revision});}return affected.length;}

export function checkTeamEligibility(rule:TeamRule|undefined,id:string){const q=rule?.eligibility;if(!q)return;const p=Object.hasOwn(q.players,id)?q.players[id]:undefined;ensure(p,'出場資格情報が未登録です：'+id);ensure(p.active,'登録休止中の選手です：'+id);ensure(!q.genders.length||q.genders.includes(p.gender),'性別の出場条件に適合しません：'+id);ensure(!q.grades.length||q.grades.includes(p.grade),'学年の出場条件に適合しません：'+id);}

