export function addEntry(t:Tournament,eid:string,name:string,club:string,players:string[],seed=0){const e=eventOf(t,eid);ensure(!t.stages.some(s=>s.eventId===eid),'組合せ作成後の参加者追加はできません');ensure(!e.entries.some(p=>p.players.length===players.length&&p.players.every(id=>players.includes(id))),'同じ選手構成が登録済みです');const p:Entry={id:uid(),name,club,players,seed};e.entries.push(p);return p;}
