export function propagate(t:Tournament,sid:string){for(const m of t.matches.filter(m=>m.stageId===sid).sort((a,b)=>a.round-b.round)){if(m.deps.length){const ds=m.deps.map(id=>t.matches.find(x=>x.id===id)!);m.left=finished(ds[0])?ds[0].winner:'';m.right=finished(ds[1])?ds[1].winner:'';if(!ds.every(finished))continue;}if((!!m.left)!=(!!m.right)){m.status='bye';m.winner=m.left||m.right;}}}
