export function guardCorrection(t:Tournament,m:Match){ensure(!descendants(t,m.id).some(n=>finished(n)||['called','playing'].includes(n.status)),'後続試合から結果・進行を取消してください');ensure(!t.stages.some(s=>s.source===m.stageId),'決勝作成後の予選訂正は保護されています。大会を複製して確認してください');}
function scoreInto(t:Tournament,id:string,games:Game[],walkover=''){const m=t.matches.find(m=>m.id===id);ensure(m&&m.left&&m.right,'対戦者が未確定です');ensure(walkover||eventOf(t,m.eventId).type!=='team','団体戦はオーダー内訳から入力してください');guardCorrection(t,m);const win=walkover?(ensure([m.left,m.right].includes(walkover),'不戦勝者が不正'),walkover):m[result(games,eventOf(t,m.eventId).rule)];delete m.decision;m.draw=false;m.walkover=!!walkover;m.finishedAt=m.status==='completed'&&m.finishedAt!==undefined?m.finishedAt:Date.now();if(walkover)m.rubbers=undefined;m.games=walkover?[]:games;m.winner=win;m.status='completed';if(walkover)t.history.push({at:new Date().toISOString(),op:uid(),action:'walkover:'+id,revision:t.revision+1});propagate(t,m.stageId);}
