 const groups=s.groups.map(g=>{if(s.kind==='league'){ensure(t.matches.filter(m=>m.groupId===g.id).length===g.entries.length*(g.entries.length-1)/2,'予選の試合が不足しています');return standings(t,g.id);}const ms=t.matches.filter(m=>m.groupId===g.id&&m.status==='completed').sort((a,b)=>b.round-a.round);ensure(ms.length&&ms.every(m=>m.winner),'勝者が確定していません');const final=ms[0];return [{id:final.winner,rank:1,tied:false},...ms.map(m=>({id:m.winner===m.left?m.right:m.left,rank:2**(final.round-m.round)+1,tied:false}))];});
