export function promote(t:Tournament,sid:string,top:number|number[],kind:'league'|'bracket',byRank=false){validate(t);const draft=structuredClone(t);promoteInto(draft,sid,top,kind,byRank);validate(draft);commitDraws(t,draft);}
function moveEntryInto(t:Tournament,sid:string,pid:string,target:string){const s=t.stages.find(s=>s.id===sid);ensure(s&&s.kind==='league'&&!s.locked&&!t.matches.some(m=>m.stageId===sid&&m.status!=='waiting')&&!t.stages.some(x=>x.source===sid),'開始前のリーグだけ調整できます');const dst=s.groups.find(g=>g.id===target);ensure(dst,'移動先なし');const src=s.groups.find(g=>g.entries.includes(pid));ensure(src&&src.entries.length>2&&src!==dst,'移動元は3組以上必要です');src.entries=src.entries.filter(x=>x!==pid);dst.entries.push(pid);t.matches=t.matches.filter(m=>m.stageId!==sid).sort((a,b)=>a.number-b.number);for(const g of s.groups)for(let i=0;i<g.entries.length;i++)for(let j=i+1;j<g.entries.length;j++)newMatch(t,s,g.id,g.entries[i],g.entries[j]);}
function scheduleInto(t:Tournament,start=540,duration=20,gap=0){ensure(Number.isInteger(start)&&start>=0&&Number.isInteger(duration)&&duration>0&&Number.isInteger(gap)&&gap>=0,'予定設定が不正');const free=Array(t.courts).fill(start),players=new Map<string,number>(),end=new Map<string,number>();for(const m of t.matches){if(m.status==='bye'){end.set(m.id,start);continue;}const s=t.stages.find(s=>s.id===m.stageId)!;const deps=[...m.deps,...t.matches.filter(x=>x.stageId===s.source).map(x=>x.id)];const pool=(id:string):string[]=>{const n=t.matches.find(x=>x.id===id)!;return n.left&&n.right?[n.left,n.right].flatMap(p=>entryOf(t,p)!.players):n.deps.flatMap(pool);};const ps=pool(m.id);const at=Math.max(start,...deps.map(d=>end.get(d)||start),...ps.map(p=>players.get(p)||start));const options=free.map(n=>Math.max(n,at)),c=options.indexOf(Math.min(...options));ensure(options[c]+duration<1440,'予定が翌日に及びます');m.court=c+1;m.time=options[c];m.duration=duration;free[c]=m.time+duration+gap;end.set(m.id,free[c]);ps.forEach(p=>players.set(p,free[c]));}}
