function teamOrderInto(t:Tournament,id:string,orders:{left:string[];right:string[]}[]){const m=t.matches.find(m=>m.id===id);ensure(m&&eventOf(t,m.eventId).type==='team'&&m.left&&m.right,'団体試合がありません');ensure(!finished(m)&&!['called','playing'].includes(m.status)&&!m.rubbers?.some(r=>r.games.length),'得点入力済みオーダーは変更できません');const tr=eventOf(t,m.eventId).team;if(tr)ensure(orders.length===tr.rubbers,'規定の対戦本数と異なります');for(const side of ['left','right'] as const){const counts=new Map<string,number>();orders.forEach((o,i)=>{if(tr)ensure(o[side].length===tr.orderSizes[i],'S/Dの順番が異なります');for(const p of o[side]){checkTeamEligibility(tr,p);const count=(counts.get(p)||0)+1;ensure(count<=(tr?.maxAppearances||9),'出場回数制限超過');counts.set(p,count);}});}ensure(orders.length>=1&&orders.length<=9&&(tr||orders.length%2===1),'団体本数は設定した1〜9本です');m.rubbers=orders.map(o=>{ensure(o.left.length>=1&&o.left.length<=2&&o.left.length===o.right.length&&new Set(o.left).size===o.left.length&&new Set(o.right).size===o.right.length,'オーダー人数が不正');ensure(o.left.every(p=>entryOf(t,m.left)!.players.includes(p))&&o.right.every(p=>entryOf(t,m.right)!.players.includes(p)),'登録選手を選んでください');return {...o,games:[],winner:''};});}
