function teamScoreInto(t:Tournament,id:string,index:number,games:Game[]){const m=t.matches.find(m=>m.id===id);ensure(m&&eventOf(t,m.eventId).type==='team'&&Number.isInteger(index)&&m.rubbers?.[index],'オーダーがありません');guardCorrection(t,m);const priorStatus=m.status,w=result(games,eventOf(t,m.eventId).rule),tr=eventOf(t,m.eventId).team;ensure(tr?.mode!=='first'||!m.winner||m.rubbers[index].games.length,'先取制の勝敗は確定済みです');m.rubbers[index].games=games;m.rubbers[index].winner=w;refreshTeam(t,m,priorStatus);}
