export function score(t:Tournament,id:string,games:Game[],walkover=''){return atomicMutation(t,d=>scoreInto(d,id,games,walkover));}

export function cancel(t:Tournament,id:string){return atomicMutation(t,d=>cancelInto(d,id));}

export function teamScore(t:Tournament,id:string,index:number,games:Game[]){return atomicMutation(t,d=>teamScoreInto(d,id,index,games));}

export function teamCancelRubber(t:Tournament,id:string,index:number){return atomicMutation(t,d=>teamCancelRubberInto(d,id,index));}

export function teamOrder(t:Tournament,id:string,orders:{left:string[];right:string[]}[]){return atomicMutation(t,d=>teamOrderInto(d,id,orders));}

export function moveEntry(t:Tournament,sid:string,pid:string,target:string){return atomicMutation(t,d=>moveEntryInto(d,sid,pid,target));}

export function schedule(t:Tournament,start=540,duration=20,gap=0){return atomicMutation(t,d=>scheduleInto(d,start,duration,gap));}

export function flow(t:Tournament){return atomicMutation(t,d=>flowInto(d));}

function teamDecideInto(t:Tournament,id:string,winner:string,reason:string){const m=t.matches.find(m=>m.id===id);ensure(m&&eventOf(t,m.eventId).type==='team'&&eventOf(t,m.eventId).team?.tieBreak==='manual'&&t.stages.find(s=>s.id===m.stageId)?.kind==='bracket','手動決着を設定した団体トーナメントを選択してください');guardCorrection(t,m);ensure(typeof reason==='string'&&reason.trim()&&reason.length<=1000,'決着理由と大会規定の根拠を入力してください（1000文字以内）');ensure(winner===m.left||winner===m.right,'決着勝者が対戦者に含まれていません');const rs=m.rubbers;ensure(rs&&rs.length>0&&rs.every(r=>r.winner)&&rs.filter(r=>r.winner==='left').length===rs.filter(r=>r.winner==='right').length,'全本が同点で終了した団体試合のみ決着を入力できます');const before=structuredClone(m),at=new Date().toISOString();m.decision={winner,reason:reason.trim(),at,basis:JSON.stringify(rs)};m.draw=false;m.walkover=false;m.winner=winner;m.finishedAt=m.status==='completed'?m.finishedAt:Date.now();m.status='completed';propagate(t,m.stageId);(t.corrections??=[]).push({at,matchId:id,reason:'同点決着：'+reason.trim(),before,after:structuredClone(m)});t.history.push({at,op:uid(),action:'団体同点決着：'+reason.trim(),revision:t.revision+1});}
export function teamDecide(t:Tournament,id:string,winner:string,reason:string){return atomicMutation(t,d=>teamDecideInto(d,id,winner,reason));}

/** RC5: swap two league positions before any match has begun. */
export function swapEntries(t:Tournament,sid:string,first:string,second:string){
 return atomicMutation(t,d=>{
  const s=d.stages.find(x=>x.id===sid);
  ensure(s&&s.kind==='league'&&!s.locked&&!d.stages.some(x=>x.source===sid),'編集できる予選リーグがありません');
  ensure(!d.matches.some(m=>m.stageId===sid&&m.status!=='waiting'),'試合開始後は編集できません');
  const a=s.groups.find(g=>g.entries.includes(first)),b=s.groups.find(g=>g.entries.includes(second));
  ensure(a&&b&&first!==second,'交換対象が不正です');
  const ai=a.entries.indexOf(first),bi=b.entries.indexOf(second);
  a.entries[ai]=second;b.entries[bi]=first;
  d.matches=d.matches.filter(m=>m.stageId!==sid);
  for(const g of s.groups)for(let i=0;i<g.entries.length;i++)for(let j=i+1;j<g.entries.length;j++)newMatch(d,s,g.id,g.entries[i],g.entries[j]);
 });
}

// RC5: swap two first-round bracket participants without changing match IDs.
// BYE positions are preserved; only actual registered entries may be exchanged.
export function swapBracketEntries(t:Tournament,sid:string,first:string,second:string){
 return atomicMutation(t,d=>{
  const stage=d.stages.find(s=>s.id===sid);
  ensure(stage&&stage.kind==='bracket'&&!stage.locked&&!stage.source&&!d.stages.some(s=>s.source===sid),'編集可能な初期トーナメントがありません');
  const matches=d.matches.filter(m=>m.stageId===sid);
  ensure(matches.every(m=>m.status==='waiting'||m.status==='bye'),'試合開始後は組合せを変更できません');
  ensure(matches.every(m=>!m.games.length&&!m.rubbers?.length&&!m.startedAt&&!m.finishedAt),'得点入力後は変更できません');
  const firstRound=matches.filter(m=>m.round===1);
  const slots=firstRound.flatMap(m=>[m.left,m.right]);
  ensure(first&&second&&first!==second&&slots.includes(first)&&slots.includes(second),'交換する選手が見つかりません');
  for(const m of firstRound){if(m.left===first)m.left=second;else if(m.left===second)m.left=first;if(m.right===first)m.right=second;else if(m.right===second)m.right=first;}
  const group=stage.groups[0];
  if(group){const a=group.entries.indexOf(first),b=group.entries.indexOf(second);if(a>=0&&b>=0){group.entries[a]=second;group.entries[b]=first;}}
  for(const m of matches){m.status='waiting';m.winner='';m.games=[];m.draw=false;m.walkover=false;}
  propagate(d,sid);
 });
}

export function removeEntry(t:Tournament,eid:string,id:string){return atomicMutation(t,d=>{const e=eventOf(d,eid);ensure(!d.stages.some(s=>s.eventId===eid),'組合せ作成後の削除は保護されています。先に組合せを保管・取消してください');ensure(e.entries.some(p=>p.id===id),'選手がありません');e.entries=e.entries.filter(p=>p.id!==id);});}

export function promoteMatchSlots(t:Tournament,sid:string,slots:{matchId:string;side:'winner'|'loser'}[]){
 return atomicMutation(t,d=>{
  const source=d.stages.find(s=>s.id===sid);
  ensure(source?.kind==='bracket','予選トーナメントを選択してください');
  ensure(!d.stages.some(s=>s.source===sid),'決勝作成済み');
  ensure(slots.length>=2&&slots.length<=512,'決勝の参加者枠は2〜512です');
  const matches=new Map(d.matches.filter(m=>m.stageId===sid).map(m=>[m.id,m]));
  ensure([...matches.values()].every(finished),'予選全試合を終了してください');
  const refs=new Set<string>();
  const ids=slots.map(({matchId,side})=>{
   ensure(side==='winner'||side==='loser','進出条件が不正');
   ensure(!refs.has(matchId+side),'同一の進出元が重複しています');refs.add(matchId+side);
   const m=matches.get(matchId);
   ensure(m?.status==='completed'&&m.winner&&m.left&&m.right,'進出元の対戦結果が未確定です');
   return side==='winner'?m.winner:m.winner===m.left?m.right:m.left;
  });
  ensure(new Set(ids).size===ids.length,'同じ選手・チームが決勝に重複します');
  let size=2;while(size<ids.length)size*=2;
  let positions=[0,1];while(positions.length<size){const n=positions.length*2;positions=positions.flatMap(x=>[x,n-1-x]);}
  const order=Array<string>(ids.length);
  positions.filter(i=>i<ids.length).forEach((i,slot)=>order[i]=ids[slot]);
  return drawInto(d,source.eventId,'bracket',1,'manual',order,sid,'決勝（進出元指定）').id;
 });
}

export function saveFinalSlots(t:Tournament,sid:string,slots:NonNullable<Stage['finalSlots']>){
 return atomicMutation(t,d=>{
  const stage=d.stages.find(s=>s.id===sid);
  ensure(stage?.kind==='bracket'&&!d.stages.some(s=>s.source===sid),'決勝生成前の予選トーナメントを選択してください');
  stage.finalSlots=slots.map(slot=>({...slot}));
 });
}

export function resolveFinalSlot(t:Tournament,slot:NonNullable<Stage['finalSlots']>[number]){
 const m=t.matches.find(m=>m.id===slot.matchId);
 if(!m||m.status!=='completed'||!m.winner)return undefined;
 return slot.side==='winner'?m.winner:m.winner===m.left?m.right:m.left;
}
