import {ensure} from './model.js';
async function key(password:string,salt:Uint8Array,usage:KeyUsage[]){ensure(password.length>=8,'パスワードは8文字以上');const raw=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:salt as Uint8Array<ArrayBuffer>,iterations:210000,hash:'SHA-256'},raw,{name:'AES-GCM',length:256},false,usage);}
export async function encrypt(bytes:ArrayBuffer,password:string){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},await key(password,salt,['encrypt']),bytes);return new Blob([new TextEncoder().encode('BDMTE001'),salt,iv,cipher],{type:'application/octet-stream'});}
export async function decrypt(bytes:ArrayBuffer,password:string){const b=new Uint8Array(bytes);ensure(bytes.byteLength>=52&&bytes.byteLength<=31*1024*1024&&new TextDecoder().decode(b.slice(0,8))==='BDMTE001','暗号ファイル形式不正');try{return await crypto.subtle.decrypt({name:'AES-GCM',iv:b.slice(24,36)},await key(password,b.slice(8,24),['decrypt']),b.slice(36));}catch{throw Error('パスワードが違うか暗号ファイルが破損しています');}}
