import JSZip from 'jszip';
import {inspectZip} from './zip-safety.js';
import {ensure,validate} from './model.js';
import type {Tournament} from './model.js';
import {hash} from './storage.js';
export async function pack(t:Tournament){validate(t);const json=JSON.stringify(t);ensure(new TextEncoder().encode(json).length<=25*1024*1024,'大会JSONが25MBを超えます。保管組合せ・履歴も別途書き出して容量を確認してください');const manifest={format:'bdmt',formatVersion:1,schemaVersion:t.schema,tournamentId:t.id,revision:t.revision,sha256:await hash(json),bytes:new TextEncoder().encode(json).length,created:new Date().toISOString()};return new JSZip().file('manifest.json',JSON.stringify(manifest)).file('tournament.json',json).generateAsync({type:'blob',compression:'STORE'});}
export async function unpack(bytes:ArrayBuffer){ensure(bytes.byteLength<=30*1024*1024,'パッケージは30MB以内です');inspectZip(bytes,26*1024*1024,2);const zip=await JSZip.loadAsync(bytes,{checkCRC32:true});ensure(Object.keys(zip.files).length===2&&zip.file('manifest.json')&&zip.file('tournament.json'),'パッケージ構成が不正');const meta=JSON.parse(await zip.file('manifest.json')!.async('string'));ensure(meta.format==='bdmt'&&meta.formatVersion===1&&[1,2].includes(meta.schemaVersion)&&Number.isInteger(meta.bytes)&&meta.bytes<=25*1024*1024,'形式・バージョンが不一致');const json=await zip.file('tournament.json')!.async('string');ensure(new TextEncoder().encode(json).length===meta.bytes&&await hash(json)===meta.sha256,'SHA-256照合に失敗しました');const t=validate(JSON.parse(json));ensure(t.schema===meta.schemaVersion&&t.id===meta.tournamentId&&t.revision===meta.revision,'パッケージの識別情報が不一致');return t;}
