export type Context={t:Tournament;db:Store;eid:string;sid:string;save:(action:string,fn:(t:Tournament)=>void)=>Promise<void>;render:()=>Promise<void>;notice:(s:string,error?:boolean)=>void;restoreInput:(d:{id:string;fields:Record<string,string>;page?:string;mid?:string;eid?:string;sid?:string;base:number})=>Promise<void>;open:(t:Tournament)=>Promise<void>};
const v=(id:string)=>(document.getElementById(id) as HTMLInputElement)?.value||'';const n=(id:string)=>Number(v(id));const button=(label:string,act:string,extra='')=>`<button data-act="${act}" ${extra}>${h(label)}</button>`;const input=(label:string,id:string,value:unknown='',type='text')=>`<label>${h(label)}<input id="${id}" type="${type}" value="${h(value)}"></label>`;const select=(label:string,id:string,rows:{id:string;name:string}[],value='')=>`<label>${h(label)}<select id="${id}">${rows.map(r=>`<option value="${h(r.id)}" ${r.id===value?'selected':''}>${h(r.name)}</option>`).join('')}</select></label>`;const sec=(label:string,body:string)=>`<details class="advanced"><summary>${h(label)}</summary>${body}</details>`;
