export function primeWorkbook(value:{name:string;rows:string[][]}[]){sheets=structuredClone(value);}
function mappingHtml(){return sheets.length?select('シート','sheetPick',sheets.map((s,i)=>({id:String(i),name:s.name})))+input('表示名の列番号（1開始）','colName',1,'number')+input('所属列','colClub',2,'number')+input('構成ID列','colPlayers',3,'number')+input('シード列','colSeed',4,'number')+select('1行目','hasHeader',[{id:'yes',name:'見出し'},{id:'no',name:'データ'}])+button('マッピング結果をプレビュー','xMapPreview')+button('プレビューを確認して登録','xMapImport')+'<pre id="mappedPreview"></pre>':'';}
const reason=(label='変更理由')=>{const s=prompt(label);ensure(typeof s==='string'&&s.trim(),'理由の入力が必要です');return s;};
export async function renderAdvanced(c:Context){const {t,db}=c;const e=eventOf(t,c.eid||t.events[0]?.id);const s=t.stages.find(s=>s.id===c.sid)||t.stages.find(s=>s.eventId===e.id);const masters=await db.rows<(MasterPlayer&{kind:string})>('masters');const pending=await db.rows<{id:string;action:string;expected:number}>('pending');const drafts=await db.rows<{id:string;page?:string;base:number;fields:Record<string,string>}>('drafts');let html='<section><h2>運営設定・安全な変更</h2><p>大会・種目・ステージの選択は「組合せ」画面と共通です。結果を変える操作は理由・影響確認後に保存します。</p></section>';
 if(s){html+=sec('同順位裁定',s.kind==='league'?s.groups.map(g=>{const rows=E.standings(t,g.id,false);return `<h3>${h(g.name)}</h3><p>同順位は設定された勝率・対戦差・得失ゲーム・得失点が同値のため発生します。</p>${rows.map(r=>select(`${entryOf(t,r.id)?.name}：勝率${r.rate} / 対戦差${r.rd} / G${r.gd} / 点${r.pd}`,'rank-'+r.id,rows.map((_,i)=>({id:String(i+1),name:String(i+1)+'位'})),String(rows.indexOf(r)+1))).join('')}${button('このリーグの順位を裁定','xAdjudicate',`data-group="${g.id}"`)}${button('裁定を取消','xRevoke',`data-group="${g.id}"`)}`;}).join(''):'リーグステージを選択してください');const impact=G.stageDependents(t,s.id);html+=sec('決勝取消・予選訂正・再生成',`<p>選択中：${h(s.name)}。依存決勝${impact.stages.length}、試合${impact.matches.length}、保護対象${impact.protected.length}。</p><ul>${impact.matches.map(m=>`<li>#${m.number} ${h(m.status)} ${h(entryOf(t,m.left)?.name)} 対 ${h(entryOf(t,m.right)?.name)}</li>`).join('')}</ul>${button('依存決勝を保管して取消','xCancelFinals')}${button('選択ステージを保管して再生成','xRegenerate')}<p>取消後、得点画面で予選を訂正し、「組合せ」で決勝を再生成します。操作前状態は自動世代、取消済み結果は大会内アーカイブに保持します。</p>`);html+=sec('組合せ確定・手動トーナメント枠',`<p>状態：${s.locked?'確定':'未確定'}</p>${button('確定・解除','xLock')}${s.kind==='bracket'?`<p>各枠の参加者IDを順番に1行ずつ記入。空枠は - 。全員1回ずつ、初戦の両側空欄は禁止。</p><textarea id="bracketSlots">${h(bracketSlots(t,s.id).map(id=>id||'-').join('\n'))}</textarea><ul>${s.groups[0].entries.map(id=>`<li>${h(entryOf(t,id)?.name)}：${h(id)}</li>`).join('')}</ul>${button('枠配置を保存','xBracket')}${button('同所属初戦を回避（シード固定）','xAvoid')}<p>${h(s.warnings?.join('\n')||'')}</p>`:''}`);}
 html+=sec('種目ルール・団体戦設定',`<h3>${h(e.name)}</h3>${select('競技形式','xType',[{id:'singles',name:'シングルス'},{id:'doubles',name:'ダブルス'},{id:'team',name:'団体戦'}],e.type)}${input('基本点','xBase',e.rule.base,'number')}${input('上限','xCap',e.rule.cap,'number')}${input('必要勝数','xWins',e.rule.wins,'number')}${select('デュース','xDeuce',[{id:'yes',name:'あり'},{id:'no',name:'なし'}],e.rule.deuce?'yes':'no')}${select('団体戦終了条件','xTeamMode',[{id:'first',name:'先取制'},{id:'all',name:'全本消化'}],e.team?.mode)}${input('対戦本数：S=1 D=2 の順番（例 2,1,1）','xTeamSizes',e.team?.orderSizes.join(',')||'2,1,1')}${input('同一選手の出場上限','xMaxAppear',e.team?.maxAppearances||2,'number')}${select('団体T同点の決着方式','xTieBreak',[{id:'reject',name:'同点を確定しない'},{id:'manual',name:'規定による役員の決着記録'}],e.team?.tieBreak||'reject')}${select('引分け許可（リーグのみ）','xAllowDraw',[{id:'no',name:'認めない'},{id:'yes',name:'認める'}],e.team?.allowDraw?'yes':'no')}${select('引分けの勝率算入','xDrawValue',[{id:'0.5',name:'0.5勝'},{id:'0',name:'0勝'}],String(e.team?.drawValue??0.5))}<label>出場資格JSON（省略可）<textarea id="xEligibility">${h(e.team?.eligibility?JSON.stringify(e.team.eligibility):'')}</textarea></label><p>例 {"genders":["女"],"grades":["2"],"players":{"p1":{"gender":"女","grade":"2","active":true}}}。制限を設定すると未確認選手は拒否します。</p>${input('団体順位の優先順（rate,rubber,game,point）','xRanking',e.team?.ranking.join(',')||'rate,rubber,game,point')}${button('種目・団体ルールを保存','xEventRule')}`);
 html+=sec('組合せ後の参加者変更',`<p>結果を保管して全組合せを明示的に取消してから参加者を修正できます。取消済み内容はアーカイブに残ります。</p>${button('種目の全組合せを保管・取消','xClearEventDraws')}${select('参加者','xEntry',e.entries.map(p=>({id:p.id,name:p.name})))}${input('新しい表示名（空欄なら現状）','xEntryName')}${input('所属','xEntryClub')}${input('構成選手ID（/区切り、空欄なら現状）','xEntryPlayers')}${input('受付状況','xReception','未受付')}${button('参加者を更新','xEntryUpdate')}${button('参加者を削除','xEntryRemove')}`);
 html+=sec('全大会共通マスター',`${input('氏名','masterName')}${input('フリガナ','masterKana')}${input('性別','masterGender')}${input('学年','masterGrade')}${input('所属団体名','masterClub')}${button('新しい選手を登録（同名可・別ID）','xMasterAdd')}${select('選手マスター','masterPick',masters.filter(m=>m.kind==='player').map(m=>({id:m.id,name:m.name+' / '+m.id})))}${button('選手情報を更新','xMasterEdit')}${button('選択種目へ選手を参加登録','xMasterRegister')}${button('選手の有効・休止切替','xMasterToggle')}<p>${masters.filter(m=>m.kind==='player').length}名 / ${masters.filter(m=>m.kind==='club').length}団体。マスター情報の変更は過去の大会名簿を自動で書き換えません。</p>${select('所属団体を編集','clubPick',masters.filter(m=>m.kind==='club').map(m=>({id:m.id,name:m.name})))}${input('新しい団体名','clubEditName')}${button('団体名を更新','xClubEdit')}${input('集計する大会ID（空欄は全年対象、カンマ区切り）','annualTournamentIds')}${button('大会一覧とIDを表示','xTournamentIds')}${input('成績集計年','statsYear',new Date().getFullYear())}${button('年間・大会練習成績を出力','xAnnual')}${button('有効マスター選手で練習組合せ','xMasterPractice')}${button('共通マスターを外部保存','xMasterExport')}<input type="file" id="masterImport" accept=".json">${button('マスターを重複なしで取込','xMasterImport')}`);
 html+=sec('CSV/Excelの列マッピング',`<input type="file" id="mappedFile" accept=".csv,.xlsx,.xls">${select('CSV文字コード','csvEncoding',[{id:'utf-8',name:'UTF-8'},{id:'shift_jis',name:'Shift_JIS'}])}${button('シートを読込','xReadSheets')}<div id="mappingArea">${mappingHtml()}</div>`);
 html+=sec('GAS版JSONから移行',`<input type="file" id="gasFile" accept=".json"><label>団体方式<select id="gasTeamMode"><option value="first">先取制</option><option value="all">全本消化</option></select></label><label>曖昧な団体選手名の登録ID対応（JSON、省略可）<textarea id="gasNameResolution" placeholder="{}"></textarea></label>${button('移行プレビュー・照合','xGasPreview')}${button('検査済み大会を新規取込','xGasImport')}${button('移行報告書を保存','xGasReport')}<label>練習セッション別の得点ルールJSON（省略可）<textarea id="gasPracticeRules" placeholder="{}"></textarea></label><pre id="gasReport"></pre><p>団体戦の手入力オーダー等、曖昧な形式があれば取込を停止し未変換表を報告書に残します。元データには書き込みません。</p>`);
 html+=sec('予定表CSV取込・再検証',`<p>UTF-8 CSV：試合ID,コート番号,開始分,所要分（見出しあり）。運営画面で予定を作成してから変更できます。</p><input type="file" id="scheduleFile" accept=".csv">${button('予定表取込','xScheduleImport')}${button('現在の予定を検証','xScheduleValidate')}`);
 html+=sec('全帳票・賞状',`${button('コート別・選手別・団体・樹形図を表示','xReports')}${button('帳票PDFを直接出力','xPdfReport')}${s?button('選択ステージの賞状を表示','xCertificates')+button('賞状PDFを直接出力','xPdfCertificate'):''}<label>賞状背景PNG/JPEG（2MB以内）<input type="file" id="certificateBg" accept="image/png,image/jpeg"></label>${input('横位置 px','certX',t.certificate?.x||0,'number')}${input('縦位置 px','certY',t.certificate?.y||0,'number')}${input('文字サイズ px','certFont',t.certificate?.fontSize||28,'number')}${button('賞状テンプレートを保存','xCertificateTemplate')}`);
 html+=sec('暗号化バックアップ・復元前プレビュー',`<p>AES-256-GCM、パスワード8文字以上。忘れたパスワードの復旧はできません。通常.bdmtも維持します。</p>${input('パスワード','backupPassword','','password')}${button('暗号化大会ファイルを出力','xEncrypt')}<input type="file" id="encryptedFile" accept=".bdmtx">${button('復号して別大会へ復元','xDecrypt')}`);
 html+=sec('外部バックアップ確認と世代整理',`<p>${h(await backupStatus(db,t))}</p>${button('外部ファイルの保存実物を確認した','xBackupConfirm')}${button('全20世代を外部JSONへ保存','xHistoryExport')}<input type="file" id="historyFile" accept=".bdmthistory,.json">${input('残す世代数（1〜20）','historyKeep',5,'number')}${button('保存した世代JSONを検証して古い内部世代を整理','xHistoryPrune')}${button('世代JSONから別大会として復元','xHistoryRestore')}<p>外部ファイルを選び直しSHAを検証してから整理します。操作ID・削除保護記録は消去しません。</p>`);
 html+=sec('再試行・下書き・履歴管理',`<p>再試行待ち${pending.length}件</p>${pending.map(p=>`<p>${h(p.action)} / 基準${p.expected} ${button('同操作IDで再試行','xPending',`data-id="${p.id}"`)}</p>`).join('')}<p>下書き${drafts.length}件（タブ別）。「入力値を確認」で保存済み大会と別のファイルへ取り出せます。</p>${drafts.slice(-30).map(d=>`<p>${h(d.page||d.id)} / 更新${d.base} ${button('入力値を確認','xDraftInspect',`data-id="${h(d.id)}"`)}${button('比較して選択復元','xDraftRestore',`data-id="${h(d.id)}"`)}</p>`).join('')}${button('診断ログを500件に整理','xPrune')}<p>保管した組合せ${t.archives?.length||0}件 / 訂正${t.corrections?.length||0}件</p>${button('取消済み組合せ・訂正記録を出力','xArchives')}`);return html;}
export async function advancedAction(c:Context,act:string,b:HTMLElement){const {t,db,eid}=c;const s=t.stages.find(s=>s.id===c.sid)||t.stages.find(s=>s.eventId===eid);switch(act){
 case 'xAdjudicate':{const gid=b.dataset.group!,g=t.stages.flatMap(s=>s.groups).find(g=>g.id===gid)!;const order=g.entries.map(id=>({id,rank:n('rank-'+id)})).sort((a,b)=>a.rank-b.rank);ensure(new Set(order.map(x=>x.rank)).size===order.length,'順位を重複なく指定してください');const r=reason('裁定理由（大会規定・決定方法）');await c.save('順位手動裁定',x=>G.adjudicate(x,gid,order.map(x=>x.id),r));break;}
 case 'xRevoke':{const r=reason('裁定取消理由');await c.save('裁定取消',x=>G.revokeRuling(x,b.dataset.group!,r));break;}
 case 'xCancelFinals':{ensure(s,'ステージなし');const impact=G.stageDependents(t,s.id);const r=reason('決勝取消・元結果訂正の理由');ensure(confirm(`決勝${impact.matches.length}試合をアーカイブに保管し、進行から除外しますか？`),'操作を中止しました');const ack=impact.protected.length?confirm(`入力済み結果${impact.protected.length}試合も保管して取消すことを承認しますか？`):false;await c.save('決勝取消・結果保管',x=>G.cancelFinals(x,s.id,r,ack));break;}
 case 'xRegenerate':{ensure(s,'ステージなし');const r=reason('再生成理由');const ack=confirm('現在の結果をアーカイブに保管し、新しい組合せを作成しますか？');ensure(ack,'操作を中止しました');await c.save('組合せ再生成',x=>{G.regenerate(x,s.id,r,ack);});break;}
 case 'xLock':{ensure(s,'ステージなし');const r=reason();await c.save('組合せ確定状態',x=>lockDraw(x,s.id,!s.locked,r));break;}
 case 'xBracket':{ensure(s,'ステージなし');const r=reason();const slots=v('bracketSlots').split(/\r?\n/).map(x=>x.trim()==='-'?'':x.trim());await c.save('手動枠配置',x=>editBracket(x,s.id,slots,r));break;}
 case 'xAvoid':ensure(s,'ステージなし');await c.save('同所属回避',x=>{avoidClubs(x,s.id);});break;
 case 'xEventRule':{const r=reason();await c.save('種目設定',x=>{const type=v('xType') as 'singles'|'doubles'|'team',sizes=v('xTeamSizes').split(',').map(Number);G.updateEvent(x,eid,{type,rule:{base:n('xBase'),cap:v('xDeuce')==='yes'?n('xCap'):n('xBase'),wins:n('xWins'),deuce:v('xDeuce')==='yes'},...(type==='team'?{team:{...(v('xTieBreak')==='manual'?{tieBreak:'manual' as const}:{}),allowDraw:v('xAllowDraw')==='yes',drawValue:Number(v('xDrawValue')) as 0|0.5,...(v('xEligibility').trim()?{eligibility:JSON.parse(v('xEligibility'))}:{}),mode:v('xTeamMode') as 'first',rubbers:sizes.length,maxAppearances:n('xMaxAppear'),orderSizes:sizes,ranking:v('xRanking').split(',') as ('rate'|'rubber'|'game'|'point')[]}}:{})},r);});break;}
 case 'xClearEventDraws':{const r=reason('全組合せ取消理由');const ms=t.matches.filter(m=>m.eventId===eid);ensure(!ms.some(m=>['called','playing'].includes(m.status)),'呼出・試合中の取消が先です');ensure(confirm(`種目の${ms.length}試合を結果ごと保管して取消しますか？`),'中止');await c.save('参加者変更前の組合せ保管',x=>G.archive(x,x.stages.filter(s=>s.eventId===eid).map(s=>s.id),r));break;}
 case 'xEntryUpdate':case 'xEntryRemove':{const p=eventOf(t,eid).entries.find(p=>p.id===v('xEntry'));ensure(p,'参加者なし');const r=reason();await c.save('参加者変更：'+r,x=>G.replaceEntry(x,eid,{...p,name:v('xEntryName')||p.name,club:v('xEntryClub'),players:v('xEntryPlayers')?v('xEntryPlayers').split('/'):p.players,reception:v('xReception')},act==='xEntryRemove'));break;}
 case 'xMasterAdd':{let club=(await db.rows<{id:string;name:string;kind:string}>('masters')).find(m=>m.kind==='club'&&m.name===v('masterClub'));if(!club&&v('masterClub')){club={id:uid(),name:v('masterClub'),kind:'club'};await saveClub(db,{...club,status:'有効'});}await savePlayer(db,{id:uid(),name:v('masterName'),kana:v('masterKana'),gender:v('masterGender'),grade:v('masterGrade'),clubId:club?.id||'',status:'有効'});await c.render();break;}
 case 'xMasterEdit':case 'xMasterToggle':{const p=(await db.rows<MasterPlayer>('masters')).find(p=>p.id===v('masterPick'));ensure(p,'選手なし');await savePlayer(db,{...p,...(act==='xMasterToggle'?{status:p.status==='有効'?'休止':'有効'}:{name:v('masterName')||p.name,kana:v('masterKana'),gender:v('masterGender'),grade:v('masterGrade')})});await c.render();break;}
 case 'xMasterRegister':{const p=(await db.rows<MasterPlayer>('masters')).find(p=>p.id===v('masterPick'));ensure(p,'選手なし');const club=(await db.rows<{id:string;name:string}>('masters')).find(m=>m.id===p.clubId);await c.save('マスターから参加登録',x=>{void registerMaster(x,eid,p,club?.name||'');});break;}
 case 'xMasterExport':download(new Blob([JSON.stringify({format:'bdmt-masters-v1',rows:await db.rows('masters')},null,2)],{type:'application/json'}),'共通マスター.json');break;
 case 'xMasterImport':{const f=(document.getElementById('masterImport') as HTMLInputElement).files?.[0];ensure(f&&f.size<=5*1024*1024,'5MB以内のマスターJSONを選択');const data=JSON.parse(await f.text()) as {format:string;rows:({id:string;name:string;kind:string}&Partial<MasterPlayer>)[]};ensure(data.format==='bdmt-masters-v1'&&Array.isArray(data.rows)&&data.rows.length<=10000,'形式不正');for(const p of data.rows)ensure(/^[\w-]{1,100}$/.test(p.id)&&p.name?.trim()&&['club','player'].includes(p.kind)&&(p.kind==='club'||typeof p.clubId==='string'&&['有効','休止'].includes(p.status||'')),'マスター項目不正');ensure(confirm(`${data.rows.length}件を追加。ID重複は全体を拒否します。`),'中止');await db.insertMany('masters',data.rows);await c.render();break;}
 case 'xMasterPractice':{const players=(await db.rows<(MasterPlayer&{kind:string})>('masters')).filter(p=>p.kind==='player'&&p.status==='有効');const rounds=Number(prompt('練習の巡数','5'));ensure(Number.isInteger(rounds),'巡数を入力');await c.save('マスター連携練習',x=>{generatePracticeFromMasters(x,players,x.courts,rounds);});break;}
 case 'xClubEdit':{const club=(await db.rows<{id:string;name:string;status:string;kind:string}>('masters')).find(m=>m.kind==='club'&&m.id===v('clubPick'));ensure(club,'団体なし');await saveClub(db,{...club,name:v('clubEditName')});await c.render();break;}
 case 'xTournamentIds':{const rows=await db.list();alert(rows.map(r=>r.name+' : '+r.id).join('\n'));break;}
 case 'xAnnual':{const all=await db.list(),tours:Tournament[]=[];const ids=v('annualTournamentIds').split(',').map(x=>x.trim()).filter(Boolean);ensure(ids.every(id=>all.some(r=>r.id===id&&!r.error)),'集計大会IDが不正');for(const row of all)if(!row.error&&(!ids.length||ids.includes(row.id)))tours.push(await db.load(row.id));download(new Blob([csv([['ID','名前','試合','勝','得点','失点','参加大会'],...annualStats(tours,v('statsYear')).map(r=>[r.id,r.name,r.played,r.wins,r.pointsFor,r.pointsAgainst,r.events.length])])]),'年間成績.csv');break;}
 case 'xReadSheets':{const f=(document.getElementById('mappedFile') as HTMLInputElement).files?.[0];ensure(f,'名簿を選択');sheets=[];sheets=await readSheets(await f.arrayBuffer(),f.name,v('csvEncoding'));document.getElementById('mappingArea')!.innerHTML=mappingHtml();break;}
 case 'xMapPreview':case 'xMapImport':{const sheet=sheets[n('sheetPick')];ensure(sheet,'シートなし');const rows=mapRoster(sheet.rows,{name:n('colName')-1,club:n('colClub')-1,players:n('colPlayers')-1,seed:n('colSeed')-1},v('hasHeader')==='yes');if(act==='xMapPreview')document.getElementById('mappedPreview')!.textContent=JSON.stringify(rows,null,2);else{ensure(confirm(`${rows.length}組を追加しますか？`),'中止');await c.save('列マッピング取込',x=>rows.forEach(r=>E.addEntry(x,eid,r.name,r.club,r.players,r.seed)));}break;}
 case 'xGasPreview':{migration=undefined;const f=(document.getElementById('gasFile') as HTMLInputElement).files?.[0];ensure(f&&f.size<=25*1024*1024,'25MB以内のGAS JSONを選択');migration=migrateGas(JSON.parse(await f.text()),{teamMode:v('gasTeamMode')==='all'?'all':'first',nameResolution:JSON.parse(v('gasNameResolution')||'{}'),practiceRules:JSON.parse(v('gasPracticeRules')||'{}')});document.getElementById('gasReport')!.textContent=JSON.stringify({counts:migration.counts,warnings:migration.warnings,errors:migration.errors,retained:migration.retained.map(r=>({table:r.table,rows:r.data.length-1}))},null,2);break;}
 case 'xGasImport':ensure(migration&&!migration.errors.length,'先にプレビューし、エラーを解消してください');ensure(confirm(`${migration.tournaments.length}大会を別IDで取り込みますか？`),'中止');await db.importBundle(migration.tournaments,migration.masterRecords);c.notice('別大会として取込完了。移行報告書も保存してください');break;
 case 'xGasReport':ensure(migration,'先にプレビュー');download(new Blob([JSON.stringify(migration,null,2)],{type:'application/json'}),'GAS移行報告.json');break;
 case 'xScheduleImport':{const f=(document.getElementById('scheduleFile') as HTMLInputElement).files?.[0];ensure(f,'CSVを選択');const rows=(await readSheets(await f.arrayBuffer(),f.name))[0].rows.slice(1);await c.save('予定表取込',x=>{const ids=new Set<string>();for(const r of rows){ensure(!ids.has(r[0]),'試合ID重複');ids.add(r[0]);const m=x.matches.find(m=>m.id===r[0]);ensure(m&&m.status==='waiting','未開始試合IDを指定');Object.assign(m,{court:Number(r[1]),time:Number(r[2]),duration:Number(r[3])});}validateSchedule(x);});break;}
 case 'xScheduleValidate':validateSchedule(t);c.notice('予定のコート・選手・依存関係・休憩を確認しました');break;
 case 'xPdfReport':{c.notice('PDF作成中…');const bytes=await generateReportPdf(t,await loadPdfFont());download(new Blob([new Uint8Array(bytes)],{type:'application/pdf'}),'大会帳票.pdf');c.notice('PDFを作成しました。保存先で確認してください');break;}
 case 'xPdfCertificate':{ensure(s,'ステージなし');const bytes=await generateCertificatePdf(t,s.id,await loadPdfFont());download(new Blob([new Uint8Array(bytes)],{type:'application/pdf'}),'賞状.pdf');break;}
 case 'xReports':document.getElementById('main')!.innerHTML=button('印刷・PDF保存','print')+reportHtml(t);break;
 case 'xCertificates':ensure(s,'ステージなし');document.getElementById('main')!.innerHTML=button('印刷・PDF保存','print')+certificateHtml(t,s.id);break;
 case 'xCertificateTemplate':{const f=(document.getElementById('certificateBg') as HTMLInputElement).files?.[0];let background=t.certificate?.background||'';if(f){ensure(['image/png','image/jpeg'].includes(f.type)&&f.size<=2*1024*1024,'PNG/JPEG 2MB以内');background=await new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=()=>reject(r.error);r.readAsDataURL(f);});}const template={background,x:n('certX'),y:n('certY'),fontSize:n('certFont')};ensure(Math.abs(template.x)<=200&&Math.abs(template.y)<=300&&template.fontSize>=12&&template.fontSize<=80,'位置・文字サイズを確認');await c.save('賞状テンプレート',x=>{x.certificate=template;});await db.put('templates',{id:'certificate',...template});break;}
 case 'xEncrypt':{const blob=await pack(t);download(await encrypt(await blob.arrayBuffer(),v('backupPassword')),'大会暗号バックアップ.bdmtx');break;}
 case 'xDecrypt':{const f=(document.getElementById('encryptedFile') as HTMLInputElement).files?.[0];ensure(f&&f.size<=31*1024*1024,'暗号大会ファイルを選択');const tour=await unpack(await decrypt(await f.arrayBuffer(),v('backupPassword')));ensure(confirm(`${tour.name} / ${tour.matches.length}試合 / 更新${tour.revision}。別大会へ復元しますか？`),'中止');await c.open(await db.importCopy(tour));break;}
 case 'xPending':await c.open(await db.retryPending(b.dataset.id!));break;
 case 'xDraftRestore':{const d=(await db.rows<{id:string;fields:Record<string,string>;page?:string;mid?:string;eid?:string;sid?:string;base:number}>('drafts')).find(d=>d.id===b.dataset.id);ensure(d,'下書きなし');await c.restoreInput(d);break;}
 case 'xDraftInspect':{const d=(await db.rows<{id:string;fields:Record<string,string>;base:number}>('drafts')).find(d=>d.id===b.dataset.id);ensure(d,'下書きなし');download(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}),'入力下書き.json');break;}
 case 'xBackupConfirm':ensure(confirm('ファイルアプリ等で.bdmt/.bdmtxの実物を確認しましたか？作成ボタンだけでは外部保存の保証になりません。'),'未確認');await confirmBackup(db,t);await c.render();break;
 case 'xHistoryExport':download(new Blob([await historyExport(db,t)],{type:'application/json'}),'世代バックアップ.bdmthistory');break;
 case 'xHistoryPrune':case 'xHistoryRestore':{const f=(document.getElementById('historyFile') as HTMLInputElement).files?.[0];ensure(f&&f.size<=40*1024*1024,'40MiB以内の世代JSONを選択');const text=await f.text(),proof=await readHistory(text);if(act==='xHistoryPrune'){ensure(confirm('外部ファイルに含まれる古い内部世代だけを削除します。続けますか？'),'中止');await pruneSnapshots(db,t,text,n('historyKeep'));c.notice('世代のSHAを照合し内部世代を整理しました');}else{const revision=Number(prompt('復元する更新番号：'+[proof.current,...proof.snapshots].map(r=>r.revision).join(',')));const row=[proof.current,...proof.snapshots].find(r=>r.revision===revision);ensure(row,'世代なし');const incoming=validate(JSON.parse(row.json));ensure(confirm(incoming.name+' / 更新'+revision+' / '+incoming.matches.length+'試合を別大会へ復元しますか？'),'中止');await c.open(await db.importCopy(incoming));}break;}
 case 'xPrune':await db.pruneLogs();c.notice('診断ログを直近500件に整理しました');break;
 case 'xArchives':download(new Blob([JSON.stringify({archives:t.archives,corrections:t.corrections,rulings:t.rulings},null,2)],{type:'application/json'}),'保管組合せ・訂正履歴.json');break;
 default:throw Error('未対応の操作：'+act);
}}
