import {ensure,validate} from './model.js';import type {Tournament} from './model.js';import {Store,hash,done} from './storage.js';import type {Envelope} from './storage.js';
type Snapshot=Envelope&{tournamentId:string; savedAt:number};
type HistoryFile={format:'bdmt-history-v1';tournamentId:string;current:Envelope;snapshots:Snapshot[]};
export async function historyExport(db:Store,t:Tournament){const [current,all]=await Promise.all([db.raw(t.id),db.rows<Snapshot>('snapshots')]);ensure(current&&current.revision===t.revision,'更新競合：大会を再読込');await db.decode(current);const value:HistoryFile={format:'bdmt-history-v1',tournamentId:t.id,current,snapshots:all.filter(s=>s.tournamentId===t.id)};for(const s of value.snapshots)ensure(await hash(s.json)===s.hash,'世代の破損を検出。整理を中止');return JSON.stringify(value);}
export async function readHistory(text:string){ensure(new TextEncoder().encode(text).length<=40*1024*1024,'世代ファイルは40MiB以内');const file=JSON.parse(text) as HistoryFile;ensure(file.format==='bdmt-history-v1'&&file.current?.id===file.tournamentId&&Array.isArray(file.snapshots)&&file.snapshots.length<=20,'世代ファイル形式不正');for(const env of [file.current,...file.snapshots]){ensure(typeof env.json==='string'&&await hash(env.json)===env.hash,'世代のSHA不一致');const t=validate(JSON.parse(env.json));ensure(t.id===file.tournamentId&&t.revision===env.revision,'世代の参照不正');}return file;}
export async function pruneSnapshots(db:Store,t:Tournament,proof:string,keep:number){ensure(Number.isInteger(keep)&&keep>=1&&keep<=20,'保持世代は1〜20');const file=await readHistory(proof);ensure(file.tournamentId===t.id&&file.current.revision===t.revision,'別大会・古い世代ファイル');const tx=db.db.transaction(['snapshots','tournaments'],'readwrite'),end=done(tx);let failure:Error|undefined;const fail=(message:string)=>{failure=Error(message);tx.abort();};const r=tx.objectStore('tournaments').get(t.id);r.onsuccess=()=>{if(r.result?.hash!==file.current.hash||r.result?.revision!==t.revision){fail('更新競合：整理を中止');return;}const rows=tx.objectStore('snapshots').getAll();rows.onsuccess=()=>{const old=(rows.result as Snapshot[]).filter(s=>s.tournamentId===t.id).sort((a,b)=>b.revision-a.revision).slice(keep);if(old.some(s=>!file.snapshots.some(p=>p.id===s.id&&p.hash===s.hash))){fail('外部世代ファイルに含まれないデータがあります');return;}for(const s of old)tx.objectStore('snapshots').delete(s.id);};};try{await end;}catch(e){throw failure||e;}}
export async function confirmBackup(db:Store,t:Tournament){const current=await db.raw(t.id);ensure(current&&current.revision===t.revision,'更新競合');await db.put('templates',{id:'backup:'+t.id,revision:t.revision,hash:current.hash,confirmedAt:Date.now()});}
export async function backupStatus(db:Store,t:Tournament){const record=(await db.rows<{id:string;revision:number;confirmedAt:number}>('templates')).find(r=>r.id==='backup:'+t.id);return record&&record.revision===t.revision?'この更新の外部保存を利用者が確認済み':'この更新の外部バックアップは未確認です';}
