import {ensure} from './model.js';
import type {Entry} from './model.js';

// Ranks in top-to-bottom order, left half then right half.
export function rankPositions(size:number):number[]{
  let order=[1,2];
  while(order.length<size){
    const complement=2*order.length+1;
    order=order.flatMap((rank,i)=>i%2?[complement-rank,rank]:[rank,complement-rank]);
  }
  return order;
}
export function rankOrder(entries:Entry[],random=Math.random) {
  const remaining=entries.filter(e=>e.rank===undefined);
  const seats=Array<Entry | undefined>(entries.length).fill(undefined);
  for(const entry of entries){
    const rank=entry.rank;
    if(rank===undefined)continue;
    ensure(Number.isSafeInteger(rank)&&rank>=1&&rank<=entries.length,'ランクは参加人数以内の整数で入力してください');
    ensure(!seats[rank-1],'ランクが重複しています: '+rank);
    seats[rank-1]=entry;
  }
  for(let i=remaining.length-1;i>0;i--){
    const j=Math.floor(random()*(i+1));
    [remaining[i],remaining[j]]=[remaining[j],remaining[i]];
  }
  let next=0;
  return seats.map(entry=>entry??remaining[next++]);
}
