import {matchNumber} from './model.js';
import {leagueCrossTable,matchScore} from './reports.js';
import {PDFDocument,rgb,PageSizes} from 'pdf-lib';import type {PDFFont,PDFPage} from 'pdf-lib';import fontkit from '@pdf-lib/fontkit';import {ensure,validate,entryOf,finished} from './model.js';import type {Tournament} from './model.js';import {standings} from './engine.js';
const characterSets=new WeakMap<PDFFont,Set<number>>();
const COLOR=rgb(.58,.1,.2),INK=rgb(.12,.14,.18),LINE=rgb(.82,.83,.86);
export async function loadPdfFont(){const res=await fetch(new URL('./fonts/NotoSansJP-Regular.ttf',location.href));ensure(res.ok,'PDFフォントを読み込めません。オンライン導入を完了してから再試行してください');return new Uint8Array(await res.arrayBuffer());}
async function document(fontBytes:Uint8Array){const pdf=await PDFDocument.create();pdf.registerFontkit(fontkit);const font=await pdf.embedFont(fontBytes,{subset:false,features:{liga:false,clig:false,locl:false}});return {pdf,font};}
function safeText(font:PDFFont,value:unknown){const text=String(value??'').replace(/[\r\n\t]/g,' ');let chars=characterSets.get(font);if(!chars){chars=new Set(font.getCharacterSet());characterSets.set(font,chars);}ensure([...text].every(c=>chars.has(c.codePointAt(0)!)),'PDFフォントにない文字があります。OSの印刷/PDF保存を使用してください');ensure(text.length<=3000,'PDFのセル内容が長すぎます');return text;}
function wrap(font:PDFFont,text:string,size:number,width:number){const lines:string[]=[];let line='';for(const c of text){if(line&&font.widthOfTextAtSize(line+c,size)>width){lines.push(line);line=c;}else line+=c;}lines.push(line);return lines;}
export async function generateReportPdf(t:Tournament,fontBytes:Uint8Array){validate(t);ensure(t.matches.length<=20000,'直接PDFは20,000試合以内です。Excelまたは種目を分けて出力してください');const {pdf,font}=await document(fontBytes);const [width,height]=PageSizes.A4.slice().reverse();let page!:PDFPage,y=0;const margin=32;
 const fresh=()=>{ensure(pdf.getPageCount()<1000,'PDFが1,000ページを超えます。出力対象を分けてください');page=pdf.addPage([width,height]);y=height-30;for(const line of wrap(font,safeText(font,t.name),14,width-64)){page.drawText(line,{x:margin,y,size:14,font,color:COLOR});y-=18;}page.drawText(`${pdf.getPageCount()}`,{x:width-48,y:18,size:8,font,color:INK});y-=24;};fresh();
 const heading=(text:string)=>{const lines=wrap(font,safeText(font,text),12,width-margin*2);if(y<Math.min(lines.length*16+96,height-100))fresh();for(const line of lines){if(y<50)fresh();page.drawText(line,{x:margin,y,size:12,font,color:COLOR});y-=16;}y-=6;};
 const table=(heads:string[],rows:unknown[][])=>{const size=8.5,cw=(width-margin*2)/heads.length;const draw=(row:unknown[],header=false)=>{const cells=heads.map((_,i)=>wrap(font,safeText(font,row[i]),size,cw-8)),count=Math.max(1,...cells.map(c=>c.length));let offset=0;while(offset<count){if(y<59){fresh();if(!header)draw(heads,true);}const capacity=Math.floor((y-35-6)/12);ensure(capacity>=1,'PDFの見出しが長すぎます');const take=Math.min(count-offset,capacity),rh=Math.max(18,take*12+6);cells.forEach((all,i)=>{const lines=all.slice(offset,offset+take);if(offset&&i===0&&!lines.length)lines.push(wrap(font,safeText(font,String(row[0])+'（続）'),size,cw-8)[0]);page.drawRectangle({x:margin+i*cw,y:y-rh,width:cw,height:rh,borderColor:LINE,borderWidth:.4,...(header?{color:rgb(.96,.94,.95)}:{})});lines.forEach((text,j)=>page.drawText(text,{x:margin+i*cw+4,y:y-12-j*12,size,font,color:INK}));});y-=rh;offset+=take;if(offset<count){fresh();if(!header)draw(heads,true);}}};if(y<85)fresh();draw(heads,true);for(const row of rows)draw(row);y-=14;};const name=(id:string)=>entryOf(t,id)?.name||'未確定';
 heading('大会情報');table(['大会名'],[[t.name]]);table(['開催日','終了日','会場','主催者','状態'],[[t.date,t.endDate||'',t.venue,t.organizer||'',t.state||'']]);
 for(const s of t.stages){heading(s.name);if(s.kind==='league')for(const g of s.groups){heading(g.name);table(['順位','選手','勝','敗','分','対戦差','得失G','得失点'],standings(t,g.id).map(r=>[r.rank,name(r.id),r.wins,r.losses,r.draws,r.rd,r.gd,r.pd]));const cross=leagueCrossTable(t,g.id);heading(g.name+' 相互対戦表');table(['説明'],[[cross.note]]);if(cross.members.length<=12){table(['番号','選手名'],cross.members.map(m=>[m.number,m.name]));table(cross.headers,cross.rows);}else{table(['説明'],[['13組以上は可読性のため対戦一覧で表示します。']]);table(['番号','左','右','得点','結果'],cross.matches.map(m=>[(matchNumber(m)),name(m.left),name(m.right),matchScore(m),m.draw?'引分け':m.winner?name(m.winner):'未入力']));}}
 else {const ms=t.matches.filter(m=>m.stageId===s.id),first=ms.filter(m=>m.round===1);if(first.length<=32){fresh();heading(s.name+' 樹形図（全氏名は対戦一覧）');if(y<200){fresh();heading('樹形図（全氏名は対戦一覧）');}const max=Math.max(...ms.map(m=>m.round)),w=(width-64)/max,h=y-50,top=y-10,points=new Map<string,{x:number;y:number}>();for(const m of ms.sort((a,b)=>a.round-b.round)){const round=ms.filter(x=>x.round===m.round),at=round.indexOf(m),x=margin+(m.round-1)*w,yy=top-(at+.5)*h/round.length;points.set(m.id,{x,y:yy});for(const d of m.deps){const p=points.get(d);if(p){page.drawLine({start:{x:p.x+w-10,y:p.y},end:{x:x-5,y:p.y},thickness:.5,color:LINE});page.drawLine({start:{x:x-5,y:p.y},end:{x:x-5,y:yy},thickness:.5,color:LINE});page.drawLine({start:{x:x-5,y:yy},end:{x,y:yy},thickness:.5,color:LINE});}}const label=`#${String(matchNumber(m))} ${name(m.left)} / ${name(m.right)}`,parts=wrap(font,safeText(font,label),6.5,w-14);let short=parts[0];if(parts.length>1){while(short&&font.widthOfTextAtSize(short+'…',6.5)>w-14)short=[...short].slice(0,-1).join('');short+='…';}page.drawText(short,{x,y:yy,size:6.5,font,color:INK});}fresh();}table(['回戦','番号','左','右','得点','勝者','決着理由'],ms.filter(m=>m.status!=='bye').map(m=>[m.round,(matchNumber(m)),name(m.left),name(m.right),matchScore(m),m.draw?'引分け':m.winner?name(m.winner):'',m.decision?m.decision.reason+' / '+m.decision.at:'']));}}
 heading('試合結果一覧');table(['番号','左','右','得点','勝者','状態','決着理由'],t.matches.filter(m=>m.status!=='bye').map(m=>[(matchNumber(m)),name(m.left),name(m.right),matchScore(m),m.draw?'引分け':m.winner?name(m.winner):'',m.status,m.decision?m.decision.reason+' / '+m.decision.at:'']));
 for(let court=1;court<=t.courts;court++){const ms=t.matches.filter(m=>m.court===court).sort((a,b)=>a.time-b.time);if(!ms.length)continue;heading(court+'コート予定');table(['番号','予定時刻','所要分','左','右'],ms.map(m=>[(matchNumber(m)),String(Math.floor(m.time/60)).padStart(2,'0')+':'+String(m.time%60).padStart(2,'0'),m.duration,name(m.left),name(m.right)]));}
 const players=new Map<string,string[]>();for(const m of t.matches.filter(m=>m.status!=='bye'))for(const p of [m.left,m.right].flatMap(id=>entryOf(t,id)?.players||[])){const ns=players.get(p)||[];ns.push(String(matchNumber(m)));players.set(p,ns);}heading('選手別試合一覧');table(['選手ID','試合番号'],[...players].map(([p,ns])=>[p,[...new Set(ns)].join(' / ')]));
 for(const m of t.matches.filter(m=>m.rubbers)){heading(`団体 #${String(matchNumber(m))} ${name(m.left)} 対 ${name(m.right)}`);table(['団体結果','決着理由'],[[m.draw?'引分け':m.winner?'勝者：'+name(m.winner):'未確定',m.decision?m.decision.reason+' / '+m.decision.at:'']]);table(['順','左オーダー','右オーダー','スコア','勝者側'],m.rubbers!.map((r,i)=>[i+1,r.left.join(' / '),r.right.join(' / '),r.games.map(g=>g.join('-')).join('/'),r.winner]));}return pdf.save();
}
export async function generateCertificatePdf(t:Tournament,sid:string,fontBytes:Uint8Array){validate(t);const s=t.stages.find(s=>s.id===sid);ensure(s,'ステージなし');const matches=t.matches.filter(m=>m.stageId===sid);ensure(matches.length&&matches.every(finished),'全試合を終了してください');const ranks=s.kind==='league'?s.groups.flatMap(g=>standings(t,g.id).filter(r=>r.rank<=3).map(r=>({id:r.id,rank:r.rank}))):(()=>{const final=[...matches].sort((a,b)=>b.round-a.round)[0];ensure(final.winner,'決勝結果なし');return [{id:final.winner,rank:1},{id:final.winner===final.left?final.right:final.left,rank:2}];})();const {pdf,font}=await document(fontBytes),c=t.certificate||{background:'',x:0,y:0,fontSize:28};let bg;if(c.background)bg=c.background.startsWith('data:image/png')?await pdf.embedPng(c.background):await pdf.embedJpg(c.background);
 for(const r of ranks){const page=pdf.addPage(PageSizes.A4),{width,height}=page.getSize();if(bg)page.drawImage(bg,{x:0,y:0,width,height});const size=c.fontSize*.75;let y=height-150-c.y*.75;for(const [text,mult] of [['賞 状',1.7],[t.name,.7],[s.name,.65],[`第 ${r.rank} 位`,1],[`${entryOf(t,r.id)?.name} 様`,1],['ここにその栄誉を称え表彰します。',.65],[`${t.date} ${t.organizer||''}`,.6]] as [string,number][]){const fs=size*mult,lines=wrap(font,safeText(font,text),fs,width-100-Math.abs(c.x)*1.5);for(const line of lines){const w=font.widthOfTextAtSize(line,fs),x=(width-w)/2+c.x*.75;ensure(x>=15&&x+w<=width-15&&y>=25,'賞状の文字が用紙を超えます。位置や文字サイズを調整してください');page.drawText(line,{x,y,font,size:fs,color:INK});y-=fs*1.5;}y-=size*.8;}}
 return pdf.save();}
