import {matchNumber} from './model.js';
import * as LegacyXLS from 'xlsx';
import ExcelJS from 'exceljs';
import {inspectZip} from './zip-safety.js';
import {ensure} from './model.js';
import {standings} from './engine.js';
import {practiceRanking} from './practice.js';
import type {Tournament} from './model.js';
export function parseCsv(text:string){text=text.replace(/^\uFEFF/,'');const rows:string[][]=[];let row:string[]=[],field='',quoted=false,closed=false;for(let i=0;i<text.length;i++){const c=text[i];if(closed&&c!==','&&c!=='\n'&&c!=='\r')throw Error('CSV閉じ引用符の後が不正');if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else if(quoted){quoted=false;closed=true;}else if(!field&&!closed)quoted=true;else throw Error('CSV引用符が不正');}else if(c===','&&!quoted){row.push(field);field='';closed=false;}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x.trim()))rows.push(row);row=[];field='';closed=false;}else field+=c;}ensure(!quoted,'CSVの引用符が閉じていません');row.push(field);if(row.some(x=>x.trim()))rows.push(row);return rows;}

export async function readRows(buffer:ArrayBuffer,name:string,encoding='utf-8'){return (await readSheets(buffer,name,encoding))[0].rows;}
export function download(blob:Blob,name:string){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
export async function workbookBytes(t:Tournament){const wb=new ExcelJS.Workbook();const add=(name:string,rows:unknown[][])=>{const ws=wb.addWorksheet(name);for(const row of rows)ws.addRow(row);ws.getRow(1).font={bold:true};ws.columns.forEach(c=>c.width=20);};add('大会',[['大会名','開催日','会場','更新番号'],[t.name,t.date,t.venue,t.revision]]);add('参加者',[['種目','表示名','所属','選手ID','シード','所属内ランク'],...t.events.flatMap(e=>e.entries.map(p=>[e.name,p.name,p.club,p.players.join('/'),p.seed,p.rank??'']))]);const names=new Map(t.events.flatMap(e=>e.entries).map(p=>[p.id,p.name]));add('試合結果',[['番号','左','右','得点','勝者','状態','コート','開始分'],...t.matches.filter(m=>m.status!=='bye').map(m=>[matchNumber(m),names.get(m.left)||'',names.get(m.right)||'',m.games.map(g=>g.join('-')).join('/'),m.draw?'引分け':names.get(m.winner)||'',m.status,m.court,m.time])]);add('順位',[['ステージ','リーグ','順位','選手','勝','敗','分','対戦差','得失G','得失点'],...t.stages.filter(s=>s.kind==='league').flatMap(s=>s.groups.flatMap(g=>standings(t,g.id).map(r=>[s.name,g.name,r.rank,names.get(r.id),r.wins,r.losses,r.draws,r.rd,r.gd,r.pd])))]);add('予定表',[['番号','コート','開始分','所要分','状態'],...t.matches.filter(m=>m.status!=='bye').map(m=>[matchNumber(m),m.court,m.time,m.duration,m.status])]);add('団体内訳',[['番号','順','左構成','右構成','得点','勝者側'],...t.matches.flatMap(m=>(m.rubbers||[]).map((r,i)=>[matchNumber(m),i+1,r.left.join('/'),r.right.join('/'),r.games.map(g=>g.join('-')).join('/'),r.winner]))]);add('練習成績',[['練習','順位','選手','試合','勝','得失点'],...(t.practice||[]).flatMap(p=>practiceRanking(p).map(r=>[p.name,r.rank,r.name,r.played,r.wins,r.diff]))]);return wb.xlsx.writeBuffer();}
export async function exportXlsx(t:Tournament){const bytes=await workbookBytes(t);download(new Blob([bytes]),'大会結果.xlsx');}
export function csv(rows:unknown[][]){const safe=(x:unknown)=>{let s=String(x??'');if(/^(?:\s*[=+@-]|[\t\r])/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};return '\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\r\n');}
export async function readSheets(buffer:ArrayBuffer,name:string,encoding='utf-8'){
 ensure(buffer.byteLength<=10*1024*1024,'取込10MB以内');
 if(/\.csv$/i.test(name)){const rows=parseCsv(new TextDecoder(encoding,{fatal:true}).decode(buffer).replace(/^\uFEFF/,''));ensure(rows.length<=10000&&rows.every(r=>r.length<=200),'行数・列数の上限を超えます');return [{name:'CSV',rows}];}
 if(/\.xls$/i.test(name)){ensure(buffer.byteLength<=5*1024*1024,'旧.xlsは5MB以内');const magic=new Uint8Array(buffer);ensure([0xd0,0xcf,0x11,0xe0,0xa1,0xb1,0x1a,0xe1].every((b,i)=>magic[i]===b),'対応する旧.xlsはOLE/BIFF8形式です。ほかは.xlsxへ変換してください');const wb=LegacyXLS.read(buffer,{type:'array',cellFormula:true,sheetRows:10001});ensure(wb.SheetNames.length>0&&wb.SheetNames.length<=100,'シート数不正');return wb.SheetNames.map(name=>{const ws=wb.Sheets[name],range=LegacyXLS.utils.decode_range(ws['!fullref']||ws['!ref']||'A1');ensure(range.e.r<10000&&range.e.c<200,'行数・列数の上限を超えます');const rows:string[][]=[];for(let r=0;r<=range.e.r;r++){const row:string[]=[];for(let c=0;c<=range.e.c;c++){const cell=ws[LegacyXLS.utils.encode_cell({r,c})];ensure(!cell?.f,'数式を値へ変換してください');row.push(cell?LegacyXLS.utils.format_cell(cell):'');}rows.push(row);}return {name,rows};});}
 ensure(/\.xlsx$/i.test(name),'CSV / .xlsx / OLE .xlsを選択してください');inspectZip(buffer,25*1024*1024,2000);const wb=new ExcelJS.Workbook();await wb.xlsx.load(buffer);ensure(wb.worksheets.length>0&&wb.worksheets.length<=100,'シート数が不正です');
 return wb.worksheets.map(ws=>{ensure(ws.rowCount<=10000&&ws.columnCount<=200,'シートが大きすぎます');const rows:string[][]=[];for(let r=1;r<=ws.rowCount;r++){const row=ws.getRow(r),values:string[]=[];for(let c=1;c<=ws.columnCount;c++){const cell=row.getCell(c),source=cell.isMerged?cell.master:cell;ensure(source.type!==ExcelJS.ValueType.Formula,'数式を値へ変換してください');values.push(source.text);}rows.push(values);}return {name:ws.name,rows};});
}
export function mapRoster(rows:string[][],mapping:{name:number;club:number;players:number;seed:number},header=true){ensure(rows.length<=2001,'2000行以内');const seen=new Set<string>();return rows.slice(header?1:0).filter(r=>r.some(Boolean)).map((r,i)=>{const name=r[mapping.name]?.trim(),club=r[mapping.club]||'',players=(r[mapping.players]||name||'').split('/').map(s=>s.trim()),seed=Number(r[mapping.seed]||0);ensure(name&&players.every(Boolean)&&new Set(players).size===players.length&&Number.isInteger(seed)&&seed>=0,'不正な行：'+(i+1));const key=JSON.stringify([name,club,players]);ensure(!seen.has(key),'取込内で重複：'+name);seen.add(key);return {name,club,players,seed};});}
