import {practiceMasterId} from './gas-practice-migration.js';
import {ensure,uid,result,finished} from './model.js';import type {Tournament,Match,Game} from './model.js';
export type GasRow=Record<string,unknown>;export type GasRows=(name:string)=>GasRow[];
export type TeamMigrationOptions={nameResolution?:Record<string,string>;teamMode?:'first'|'all'};
const s=(row:GasRow,key:string)=>String(row[key]??'');
export function migrateTeams(t:Tournament,rows:GasRows,options:TeamMigrationOptions={}){
 const warnings:string[]=[],aliases:{sourceId:string;matchId:string}[]=[];const fixtures=rows('追加_団体試合').filter(f=>t.stages.some(st=>st.id===s(f,'ステージID'))),rubbers=rows('追加_団体内訳'),players=rows('選手マスター');const seenIds=new Set<string>(),seenPairs=new Set<string>();
 const formats:Record<string,number[]>={'1複2単':[2,1,1],'2複1単':[2,2,1],'3複':[2,2,2]};const numbers=t.matches.map(m=>m.number);let next=Math.max(0,...numbers);
 for(const f of fixtures){const fid=s(f,'団体試合ID'),stage=t.stages.find(st=>st.id===s(f,'ステージID'))!;ensure(!!fid&&!seenIds.has(fid),'団体試合IDが空または重複：'+fid);seenIds.add(fid);const pairKey=stage.id+':'+[s(f,'左参加ID'),s(f,'右参加ID')].sort().join('|');ensure(!seenPairs.has(pairKey),'団体対戦の重複：'+fid);seenPairs.add(pairKey);const event=t.events.find(e=>e.id===stage.eventId);ensure(event?.type==='team','団体試合の種目が不正：'+fid);const l=event.entries.find(p=>p.id===s(f,'左参加ID')),r=event.entries.find(p=>p.id===s(f,'右参加ID'));ensure(l&&r&&l.id!==r.id,'団体の所属参照が不正：'+fid);
 if(!stage.groups.length){ensure(stage.kind==='league','団体Tの枠を復元できません');stage.groups.push({id:uid(),name:stage.name+' 団体',entries:[...new Set(fixtures.filter(x=>s(x,'ステージID')===stage.id).flatMap(x=>[s(x,'左参加ID'),s(x,'右参加ID')]))]});warnings.push(stage.name+'：団体対戦からリーグ所属を再構成しました');}
 const group=stage.groups.find(g=>g.entries.includes(l.id)&&g.entries.includes(r.id));ensure(group,'団体リーグを一意に判定できません：'+fid);const existing=t.matches.filter(m=>m.stageId===stage.id&&[m.left,m.right].includes(l.id)&&[m.left,m.right].includes(r.id));ensure(existing.length<=1,'団体の基礎試合が重複：'+fid);let m=existing[0];const priorWinner=m?.winner||'';
 if(m){ensure(!m.rubbers&&!m.games.length,'基礎試合と団体内訳の結果が重複：'+fid);ensure(m.left===l.id&&m.right===r.id,'基礎試合と団体試合の左右が逆です：'+fid);aliases.push({sourceId:fid,matchId:m.id});}
 else{ensure(stage.kind==='league','団体Tは元のトーナメント枠が必要です：'+fid);m={id:fid,eventId:event.id,stageId:stage.id,groupId:group.id,number:++next,round:1,left:l.id,right:r.id,deps:[],games:[],winner:'',status:'waiting',court:0,time:0,duration:20};t.matches.push(m);}
 const at=rows('大会タイムテーブル').find(x=>s(x,'試合ID')===fid);if(at){const [hh,mm]=(s(at,'予定開始')||'00:00').split(':').map(Number);m.court=Number(at['コート']||0);m.time=hh*60+mm;m.duration=Number(at['予定時間分']||20);}
 const oldStatus=s(f,'試合状態'),oldWinner=s(f,'勝者参加ID');if(oldStatus==='不戦勝'){ensure(oldWinner===l.id||oldWinner===r.id,'不戦勝者が不正：'+fid);m.walkover=true;m.winner=oldWinner;m.status='completed';m.rubbers=undefined;t.history.push({at:new Date().toISOString(),op:uid(),action:'walkover:'+m.id,revision:0});continue;}
 const sizes=formats[s(f,'試合形式')||'1複2単'];ensure(sizes,'未対応の団体形式：'+s(f,'試合形式'));const declaredMode=options.teamMode||'first';if(event.team)ensure(event.team.mode===declaredMode&&event.team.orderSizes.join()===sizes.join(),'同一種目で異なる団体形式を使用：'+event.name);else event.team={mode:declaredMode,rubbers:sizes.length,maxAppearances:sizes.length,orderSizes:sizes,ranking:['rate','rubber','game','point']};const raw=rubbers.filter(x=>s(x,'団体試合ID')===fid).sort((a,b)=>Number(a['対戦順'])-Number(b['対戦順']));ensure(raw.length===sizes.length&&raw.every((x,i)=>Number(x['対戦順'])===i+1),'団体内訳の本数/順番が不正：'+fid);
 const resolve=(rawName:string,roster:string[],key:string,expected:number)=>{let names=expected===1?[rawName]:rawName.split(/[\/／・、,，+＆&]/).map(x=>x.trim());const mapped=options.nameResolution?.[key];if(mapped)names=mapped.split('/').map(x=>x.trim());ensure(names.length===expected&&names.every(Boolean),'オーダーをIDで指定してください：'+key+'（'+rawName+'）');const ids=names.map(token=>{if(roster.includes(token))return token;const hits=players.filter(p=>roster.includes(s(p,'選手ID'))&&s(p,'選手名')===token);ensure(hits.length===1,'選手名を一意に同定できません：'+key+'（'+token+'）。nameResolutionへ登録IDを指定してください');return s(hits[0],'選手ID');});ensure(new Set(ids).size===ids.length,'内訳内で同一選手が重複：'+key);return ids;};
 m.rubbers=raw.map((row,i)=>{const score=JSON.parse(s(row,'得点JSON')||'[]') as {left:number;right:number}[];ensure(Array.isArray(score),'得点JSON不正：'+fid);const games:Game[]=score.map(g=>[Number(g.left),Number(g.right)]),won=s(row,'勝者側');const leftName=s(row,'左選手名'),rightName=s(row,'右選手名');if(!leftName&&!rightName&&!games.length&&!won&&!options.nameResolution?.[`${fid}:${i+1}:left`]&&!options.nameResolution?.[`${fid}:${i+1}:right`]){return {left:[],right:[],games:[],winner:''};}const left=resolve(leftName,l.players,`${fid}:${i+1}:left`,sizes[i]),right=resolve(rightName,r.players,`${fid}:${i+1}:right`,sizes[i]);const winner=games.length?result(games,event.rule):'';ensure((won==='L'?'left':won==='R'?'right':won)===winner,'内訳勝者と得点が不一致：'+fid);return {left,right,games,winner};});
 // An entirely blank future order is retained as no submitted order. Partial blank orders require explicit completion.
 if(m.rubbers.every(x=>!x.left.length)){m.rubbers=undefined;ensure(!oldWinner&&oldStatus!=='終了','団体の結果に内訳がありません：'+fid);m.status='waiting';m.winner='';}
 else{ensure(m.rubbers.every(x=>x.left.length),'未記入オーダーを補完してください：'+fid+'（氏名を推測しません）');const a=m.rubbers.filter(x=>x.winner==='left').length,b=m.rubbers.filter(x=>x.winner==='right').length;const mode=options.teamMode||'first';const winner=(mode==='first'||m.rubbers.every(x=>x.winner))&&Math.max(a,b)>sizes.length/2?(a>b?l.id:r.id):'';ensure(winner===oldWinner&&(oldStatus==='終了')===!!winner,'団体全体の勝敗/状態が内訳と不一致：'+fid);ensure(!priorWinner||priorWinner===winner,'トーナメントと団体勝者が不一致：'+fid);m.winner=winner;m.status=winner?'completed':'waiting';
 const max=Math.max(1,...[m.rubbers.flatMap(x=>x.left),m.rubbers.flatMap(x=>x.right)].flatMap(ids=>[...new Set(ids)].map(id=>ids.filter(x=>x===id).length)));const config={mode,rubbers:sizes.length,maxAppearances:max,orderSizes:sizes,ranking:['rate','rubber','game','point'] as ('rate'|'rubber'|'game'|'point')[]};if(event.team){ensure(event.team.mode===config.mode&&event.team.orderSizes.join()===sizes.join(),'同一種目で異なる団体形式を使用：'+event.name);event.team.maxAppearances=Math.max(event.team.maxAppearances,max);}else event.team=config;}
 }
 for(const m of t.matches.filter(m=>t.events.find(e=>e.id===m.eventId)?.type==='team'&&m.status==='completed'&&!m.walkover))ensure(m.rubbers,'団体の完了結果に内訳がありません：'+m.id);
 return {warnings,aliases,sourceFixtures:fixtures.length,convertedFixtures:seenIds.size};
}
export function migrateMasterRows(rows:GasRows,tournaments:Tournament[]){const clubs=new Map<string,{id:string;kind:'club';name:string;status:string}>(),masters:{id:string;kind:'player';name:string;kana:string;gender:string;grade:string;clubId:string;status:string}[]=[],warnings:string[]=[];const club=(name:string)=>{if(!name)return '';if(!clubs.has(name)){let h=2166136261;for(const c of name)h=Math.imul(h^c.charCodeAt(0),16777619);const id='gas-club-'+(h>>>0).toString(16)+'-'+name.length;ensure(![...clubs.values()].some(c=>c.id===id&&c.name!==name),'所属IDの衝突。手動確認が必要です');clubs.set(name,{id,kind:'club',name,status:'有効'});}return clubs.get(name)!.id;};
 for(const p of rows('選手マスター')){const id=s(p,'選手ID');ensure(!masters.some(m=>m.id===id),'選手マスターID重複：'+id);masters.push({id,kind:'player',name:s(p,'選手名'),kana:s(p,'フリガナ'),gender:s(p,'性別'),grade:s(p,'学年'),clubId:club(s(p,'所属クラブ')),status:['休止','無効','0','退会'].includes(s(p,'登録状態'))?'休止':'有効'});}
 for(const p of rows('練習メンバー')){const id=practiceMasterId(s(p,'メンバーID'));ensure(!masters.some(m=>m.id===id),'練習マスターIDが競技マスターと衝突：'+id);ensure(s(p,'氏名').trim(),'練習者氏名がありません：'+id);masters.push({id,kind:'player',name:s(p,'氏名'),kana:s(p,'フリガナ'),gender:s(p,'性別'),grade:s(p,'学年'),clubId:club(s(p,'所属')),status:s(p,'有効')==='0'?'休止':'有効'});}
 for(const t of tournaments)for(const e of t.events)for(const p of e.entries){club(p.club);for(const id of p.players)if(!masters.some(m=>m.id===id)){const precise=e.type==='singles'&&p.players.length===1;masters.push({id,kind:'player',name:precise?p.name:id,kana:p.kana||'',gender:p.gender||'',grade:p.grade||'',clubId:club(p.club),status:precise?'有効':'休止'});warnings.push(id+'：元マスター欠損。'+(precise?'参加者名から補完':'氏名未確定の休止レコードとして保持'));}}
 return {records:[...clubs.values(),...masters],warnings};
}
