import {matchNumber} from './model.js';
import {entryOf,ensure,finished,validate} from './model.js';import type {Tournament,Match} from './model.js';import {standings} from './engine.js';
export const escapeHtml=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const grid=(heads:string[],rows:unknown[][])=>`<div class="table"><table class="report-grid"><thead><tr>${heads.map(h=>`<th style="white-space:normal;overflow-wrap:anywhere">${escapeHtml(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr style="break-inside:avoid">${r.map(v=>`<td style="white-space:normal;overflow-wrap:anywhere">${escapeHtml(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
function svgLines(text:string,max=16){const lines:string[]=[];let line='',units=0;for(const c of text){const u=(c.codePointAt(0)||0)>0xffff?2:1;if(units+u>max&&line){lines.push(line);line='';units=0;}line+=c;units+=u;}lines.push(line);return lines;}
export function matchScore(m:Match){if(m.status==='bye')return '初戦免除';if(m.walkover||m.status==='completed'&&m.winner&&!m.games.length&&!m.rubbers)return '不戦勝';if(m.rubbers)return m.rubbers.filter(r=>r.winner==='left').length+'-'+m.rubbers.filter(r=>r.winner==='right').length+(m.decision?'（役員決着）':!finished(m)?'（途中）':'');return m.games.map(g=>g.join('-')).join('/');}
export function bracketSvg(t:Tournament,sid:string){const matches=t.matches.filter(m=>m.stageId===sid),max=Math.max(1,...matches.map(m=>m.round)),first=matches.filter(m=>m.round===1),width=max*230,abbreviated=first.length>16;const labels=new Map(matches.map(m=>{const full=[entryOf(t,m.left)?.name||'未確定',entryOf(t,m.right)?.name||'未確定'];const parts=full.map(n=>{const lines=svgLines(n);return abbreviated&&lines.length>2?[...lines.slice(0,2),'…（対戦一覧参照）']:lines;});return [m.id,{full,parts,meta:svgLines(`#${String(matchNumber(m))} ${m.decision?'役員決着 ':m.draw?'引分け ':''}${matchScore(m)}`)}];}));const nodeHeight=Math.max(72,...[...labels.values()].map(v=>(v.parts[0].length+v.parts[1].length+v.meta.length)*14+20)),height=Math.max(160,first.length*(nodeHeight+20));const points=new Map<string,{x:number;y:number}>(),out:string[]=[];
for(const m of [...matches].sort((a,b)=>a.round-b.round)){const same=matches.filter(n=>n.round===m.round),index=same.indexOf(m),x=(m.round-1)*230,y=(index+.5)*height/same.length,label=labels.get(m.id)!;points.set(m.id,{x,y});for(const dep of m.deps){const p=points.get(dep);if(p)out.push(`<path d="M${p.x+200},${p.y} H${x-15} V${y} H${x}" fill="none" stroke="#777"/>`);}out.push(`<g><title>${escapeHtml(label.full.join(' 対 '))}</title><rect x="${x}" y="${y-nodeHeight/2}" width="200" height="${nodeHeight}" rx="5" fill="#fff" stroke="#a72135"/>`);let yy=y-nodeHeight/2+16;for(const [side,lines]of label.parts.entries()){out.push(`<text x="${x+6}" y="${yy}" font-size="11" fill="${side?'#222':'#8e2032'}">${lines.map((v,i)=>`<tspan x="${x+6}" dy="${i?14:0}">${escapeHtml(v)}</tspan>`).join('')}</text>`);yy+=lines.length*14+4;}out.push(`<text x="${x+6}" y="${yy}" font-size="10">${label.meta.map((v,i)=>`<tspan x="${x+6}" dy="${i?14:0}">${escapeHtml(v)}</tspan>`).join('')}</text></g>`);}
return `<svg role="img" aria-label="トーナメント樹形図${abbreviated?'（長名は全対戦一覧を参照）':''}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" style="min-width:${Math.min(width,1000)}px;width:100%">${out.join('')}</svg>`;}
export function leagueCrossTable(t:Tournament,gid:string){const stage=t.stages.find(s=>s.groups.some(g=>g.id===gid));ensure(stage?.kind==='league','リーグなし');const group=stage.groups.find(g=>g.id===gid)!,ids=group.entries,pair=(a:string,b:string)=>[a,b].sort().join('|'),selected=new Map<string,Tournament['matches'][number]>();if(stage.source&&t.stages.find(s=>s.id===stage.source)?.kind==='league')for(const m of t.matches.filter(m=>m.stageId===stage.source&&finished(m)&&ids.includes(m.left)&&ids.includes(m.right)))selected.set(pair(m.left,m.right),m);for(const m of t.matches.filter(m=>m.groupId===gid)){const key=pair(m.left,m.right);if(finished(m)||!selected.has(key))selected.set(key,m);}
 const members=ids.map((id,i)=>({id,number:i+1,name:entryOf(t,id)?.name||id}));const rows=ids.map((id,i)=>[String(i+1),...ids.map(other=>{if(id===other)return '—';const m=selected.get(pair(id,other));if(!m||!finished(m))return '未入力';const left=m.left===id,marker=m.draw?'分':m.winner===id?'○':'●';let score=m.walkover?'不戦勝':m.rubbers?m.rubbers.reduce((n,r)=>n+(r.winner===(left?'left':'right')?1:0),0)+'-'+m.rubbers.reduce((n,r)=>n+(r.winner===(left?'right':'left')?1:0),0):m.games.map(g=>(left?g:[g[1],g[0]]).join('-')).join('/');return marker+' '+score+(m.stageId!==stage.id?'（予選）':'');})]);return {members,headers:['選手番号 / 対戦相手',...ids.map((_,i)=>String(i+1))],rows,matches:[...selected.values()],note:'各行から見た得点。予選結果は決勝の再試合が確定するまで採用します。'};}
export function reportHtml(t:Tournament){validate(t);const name=(id:string)=>entryOf(t,id)?.name||'未確定',time=(n:number)=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');let out=`<style>.report-grid{table-layout:fixed}.report-grid thead{display:table-header-group}h2,h3,h4{break-after:avoid}.certificate{overflow-wrap:anywhere;word-break:normal}@media print{.report-grid tr{break-inside:avoid}svg{break-inside:avoid}}</style><h2>${escapeHtml(t.name)} 帳票</h2>`;for(const s of t.stages){out+=`<h3>${escapeHtml(s.name)}</h3>`;if(s.kind==='bracket')out+=`<div class="table">${bracketSvg(t,s.id)}</div>`;else for(const g of s.groups){out+=`<h4>${escapeHtml(g.name)}</h4>`+grid(['順位','選手','勝','敗','分','対戦差','得失G','得失点'],standings(t,g.id).map(r=>[r.rank,name(r.id),r.wins,r.losses,r.draws,r.rd,r.gd,r.pd]));const cross=leagueCrossTable(t,g.id);out+='<h4>相互対戦表</h4><p>'+escapeHtml(cross.note)+'</p>';if(cross.members.length<=12)out+=grid(['選手番号','選手名'],cross.members.map(m=>[m.number,m.name]))+grid(cross.headers,cross.rows);else out+='<p>13組以上は可読性のため相互表を対戦一覧に分割します。</p>'+grid(['番号','左','右','得点','結果'],cross.matches.map(m=>[(matchNumber(m)),name(m.left),name(m.right),matchScore(m),m.draw?'引分け':m.winner?name(m.winner):'未入力']));}}
 out+='<h3>試合結果一覧</h3>'+grid(['番号','左','右','得点','勝者','状態','決着理由'],t.matches.filter(m=>m.status!=='bye').map(m=>[(matchNumber(m)),name(m.left),name(m.right),matchScore(m),m.draw?'引分け':m.winner?name(m.winner):'',m.status,m.decision?m.decision.reason+' / '+m.decision.at:'']));
 for(let court=1;court<=t.courts;court++)out+=`<h3>${court}コート予定表</h3>`+grid(['予定','分','番号','左','右','状態'],t.matches.filter(m=>m.court===court).sort((a,b)=>a.time-b.time).map(m=>[time(m.time),m.duration,(matchNumber(m)),name(m.left),name(m.right),m.status]));
 const players=new Map<string,string[]>();for(const m of t.matches.filter(m=>m.status!=='bye'))for(const id of [m.left,m.right].flatMap(id=>entryOf(t,id)?.players||[])){const list=players.get(id)||[];list.push(String(matchNumber(m)));players.set(id,list);}out+='<h3>選手別試合一覧（選手ID）</h3>'+grid(['選手ID','試合番号'],[...players].map(([p,ns])=>[p,[...new Set(ns)].join(' / ')]));
 for(const m of t.matches.filter(m=>m.rubbers))out+=`<h3>団体戦 #${escapeHtml(String(matchNumber(m)))} ${escapeHtml(name(m.left))} 対 ${escapeHtml(name(m.right))}</h3><p>${escapeHtml(m.draw?'引分け':m.decision?'役員決着：'+name(m.winner)+' / '+m.decision.reason+' / '+m.decision.at:m.winner?'勝者：'+name(m.winner):'未確定')}</p>`+grid(['順','左オーダー','右オーダー','得点','勝者側'],m.rubbers!.map((r,i)=>[i+1,r.left.join(' / '),r.right.join(' / '),r.games.map(g=>g.join('-')).join('/'),r.winner]));return out;}
export function certificateHtml(t:Tournament,sid:string){validate(t);const s=t.stages.find(s=>s.id===sid);ensure(s,'ステージなし');const matches=t.matches.filter(m=>m.stageId===sid);ensure(matches.length&&matches.every(finished),'全試合を終了してください');const ranks=s.kind==='league'?s.groups.flatMap(g=>standings(t,g.id).filter(r=>r.rank<=3).map(r=>({rank:r.rank,id:r.id}))):(()=>{const final=[...matches].sort((a,b)=>b.round-a.round)[0];ensure(final?.winner,'決勝結果なし');return [{rank:1,id:final.winner},{rank:2,id:final.winner===final.left?final.right:final.left}];})();const c=t.certificate||{background:'',x:0,y:0,fontSize:28};ensure(Number.isFinite(c.x)&&Math.abs(c.x)<=200&&Number.isFinite(c.y)&&Math.abs(c.y)<=300&&c.fontSize>=12&&c.fontSize<=80&&(!c.background||/^data:image\/(png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(c.background)),'賞状設定不正');return ranks.map(r=>`<section class="certificate" style="position:relative;min-height:800px;${c.background?`background-image:url('${c.background}');background-size:100% 100%;`:''}"><div style="transform:translate(${c.x}px,${c.y}px);font-size:${c.fontSize}px;overflow-wrap:anywhere;word-break:normal"><h2>賞 状</h2><p>${escapeHtml(t.name)} ${escapeHtml(s.name)}</p><p>第 ${r.rank} 位</p><h3>${escapeHtml(entryOf(t,r.id)?.name)} 様</h3><p>ここにその栄誉を称え表彰します。</p><p>${escapeHtml(t.date)}　${escapeHtml(t.organizer||'')}</p></div></section>`).join('');}
