import {ensure,uid,result} from './model.js';
import type {Tournament,Rule,Game} from './model.js';
export type Practice={id:string;name:string;members:{id:string;name:string;masterId?:string}[];rule:Rule;matches:{id:string;round:number;court:number;left:string[];right:string[];games:Game[];winner:string}[]};
export function generatePractice(t:Tournament,names:string[],courts:number,rounds:number){ensure(names.length>=4&&names.length<=200&&new Set(names).size===names.length&&names.every(x=>x.trim()&&x.length<=80),'練習は異なる名前4〜200名');ensure(Number.isInteger(courts)&&courts>=1&&courts<=64&&Number.isInteger(rounds)&&rounds>=1&&rounds<=50,'コート・巡数が不正');const p:Practice={id:uid(),name:'練習 '+new Date().toISOString().slice(0,10),members:names.map(name=>({id:uid(),name})),rule:{base:21,cap:30,wins:1,deuce:true},matches:[]};const played=new Map(p.members.map(m=>[m.id,0])),pairs=new Map<string,number>(),opponents=new Map<string,number>(),restStreak=new Map(p.members.map(m=>[m.id,0]));const key=(a:string,b:string)=>[a,b].sort().join('|');for(let round=1;round<=rounds;round++){const random=new Map(p.members.map(m=>[m.id,Math.random()]));const pool=p.members.map(m=>m.id).sort((a,b)=>played.get(a)!-played.get(b)!||restStreak.get(b)!-restStreak.get(a)!||random.get(a)!-random.get(b)!).slice(0,Math.min(courts,Math.floor(names.length/4))*4);for(const m of p.members)restStreak.set(m.id,pool.includes(m.id)?0:restStreak.get(m.id)!+1);for(let i=0;i<pool.length;i+=4){const four=pool.slice(i,i+4),variants=[[four[0],four[1],four[2],four[3]],[four[0],four[2],four[1],four[3]],[four[0],four[3],four[1],four[2]]];const cost=(v:string[])=>4*((pairs.get(key(v[0],v[1]))||0)+(pairs.get(key(v[2],v[3]))||0))+[v[0],v[1]].reduce((n,a)=>n+[v[2],v[3]].reduce((m,b)=>m+(opponents.get(key(a,b))||0),0),0);variants.sort((a,b)=>cost(a)-cost(b));const [a,b,c,d]=variants[0];p.matches.push({id:uid(),round,court:i/4+1,left:[a,b],right:[c,d],games:[],winner:''});for(const id of four)played.set(id,played.get(id)!+1);for(const x of [a,b])for(const y of [c,d])opponents.set(key(x,y),(opponents.get(key(x,y))||0)+1);for(const [x,y] of [[a,b],[c,d]])pairs.set(key(x,y),(pairs.get(key(x,y))||0)+1);}}(t.practice??=[]).push(p);return p;}
export function practiceScore(t:Tournament,pid:string,mid:string,games:Game[]){const p=t.practice?.find(p=>p.id===pid),m=p?.matches.find(m=>m.id===mid);ensure(p&&m,'練習試合がありません');m.winner=result(games,p.rule);m.games=games;}
export function practiceRanking(p:Practice){const rows=p.members.map(member=>{let played=0,wins=0,pf=0,pa=0;for(const m of p.matches.filter(m=>m.winner&&(m.left.includes(member.id)||m.right.includes(member.id)))){played++;const left=m.left.includes(member.id);if(m.winner===(left?'left':'right'))wins++;for(const g of m.games){pf+=g[left?0:1];pa+=g[left?1:0];}}return {...member,played,wins,rate:played?wins/played:0,diff:pf-pa,rank:0};});rows.sort((a,b)=>b.rate-a.rate||b.wins-a.wins||b.diff-a.diff);rows.forEach((r,i)=>{const prev=rows[i-1];r.rank=prev&&r.rate===prev.rate&&r.wins===prev.wins&&r.diff===prev.diff?prev.rank:i+1;});return rows;}

export function generatePracticeFromMasters(t:Tournament,members:{id:string;name:string}[],courts:number,rounds:number){const p=generatePractice(t,members.map(m=>m.name+' ['+m.id+']'),courts,rounds);p.members.forEach((m,i)=>{m.name=members[i].name;m.masterId=members[i].id;});return p;}
