import {atomicMutation} from './atomic.js';
import {rankingSignature} from './ranking-basis.js';
import {ensure,uid,finished,validate,eventOf} from './model.js';
import type {Tournament,Rule,Event,Entry} from './model.js';
import {standings,draw} from './engine.js';
export function audit(t:Tournament,action:string){t.history.push({at:new Date().toISOString(),op:uid(),action,revision:t.revision+1});}
export function stageDependents(t:Tournament,sid:string){const ids=new Set<string>();let changed=true;while(changed){changed=false;for(const s of t.stages)if(s.source&&(s.source===sid||ids.has(s.source))&&!ids.has(s.id)){ids.add(s.id);changed=true;}}return {stages:t.stages.filter(s=>ids.has(s.id)),matches:t.matches.filter(m=>ids.has(m.stageId)),protected:t.matches.filter(m=>ids.has(m.stageId)&&(m.status==='completed'||['called','playing'].includes(m.status)||m.rubbers?.some(r=>r.games.length)))};}
function cancelFinalsInto(t:Tournament,sid:string,reason:string,acknowledgedResults=false){ensure(reason.trim(),'取消理由を入力してください');const impact=stageDependents(t,sid);ensure(impact.stages.length,'依存する決勝がありません');ensure(!impact.matches.some(m=>['called','playing'].includes(m.status)),'呼出・試合中の決勝は先に進行を取消してください');ensure(!impact.protected.length||acknowledgedResults,'入力済み決勝結果があります。影響一覧を確認し結果保管を明示承認してください');archive(t,impact.stages.map(s=>s.id),reason);audit(t,'決勝取消：'+reason);}
function archiveInto(t:Tournament,sids:string[],reason:string){ensure(reason.trim(),'変更理由が必要です');const ids=new Set(sids);(t.archives??=[]).push({id:uid(),at:new Date().toISOString(),reason,events:structuredClone(t.events.filter(e=>t.stages.some(s=>ids.has(s.id)&&s.eventId===e.id))),stages:structuredClone(t.stages.filter(s=>ids.has(s.id))),matches:structuredClone(t.matches.filter(m=>ids.has(m.stageId)))});t.stages=t.stages.filter(s=>!ids.has(s.id));t.matches=t.matches.filter(m=>!ids.has(m.stageId));for(const r of t.rulings||[])if(!t.stages.some(s=>s.groups.some(g=>g.id===r.groupId)))r.cancelled=new Date().toISOString();}
function adjudicateInto(t:Tournament,gid:string,order:string[],reason:string){ensure(reason.trim(),'裁定理由が必要です');const s=t.stages.find(s=>s.groups.some(g=>g.id===gid));ensure(s&&s.kind==='league','リーグなし');ensure(!stageDependents(t,s.id).stages.length,'決勝への影響があります。先に決勝取消を実施してください');ensure(t.matches.filter(m=>m.groupId===gid).every(finished),'リーグを終了してください');const rows=standings(t,gid,false);ensure(rows.some(r=>r.tied),'同順位がありません');ensure(order.length===rows.length&&new Set(order).size===rows.length&&order.every(id=>rows.some(r=>r.id===id)),'全参加者を重複なく指定してください');const positions=order.map(id=>rows.find(r=>r.id===id)!.rank);ensure(positions.every((r,i)=>!i||r>=positions[i-1]),'同順位以外の順位を変更できません');for(const r of t.rulings||[])if(r.groupId===gid&&!r.cancelled)r.cancelled=new Date().toISOString();(t.rulings??=[]).push({id:uid(),groupId:gid,order:[...order],basis:rankingSignature(t,gid,rows),reason,at:new Date().toISOString()});audit(t,'順位裁定：'+reason);}
function revokeRulingInto(t:Tournament,gid:string,reason:string){ensure(reason.trim(),'取消理由が必要です');const s=t.stages.find(s=>s.groups.some(g=>g.id===gid));ensure(s&&!stageDependents(t,s.id).stages.length,'先に依存する決勝を取消してください');const r=t.rulings?.find(r=>r.groupId===gid&&!r.cancelled);ensure(r,'有効な裁定なし');r.cancelled=new Date().toISOString();audit(t,'裁定取消：'+reason);}
function updateEventInto(t:Tournament,eid:string,patch:Partial<Pick<Event,'name'|'type'|'rule'|'team'>>,reason:string){ensure(reason.trim(),'変更理由が必要です');const e=eventOf(t,eid),structural=patch.type&&patch.type!==e.type||patch.rule&&JSON.stringify(patch.rule)!==JSON.stringify(e.rule)||patch.team&&JSON.stringify(patch.team)!==JSON.stringify(e.team);if(structural)ensure(!t.matches.some(m=>m.eventId===eid&&(m.status!=='waiting'&&m.status!=='bye'||m.rubbers?.length)),'試合開始・オーダー作成後の形式変更はできません');const copy=structuredClone(t);Object.assign(eventOf(copy,eid),patch);if(patch.type&&patch.type!=='team')delete eventOf(copy,eid).team;validate(copy);Object.assign(e,patch);if(patch.type&&patch.type!=='team')delete e.team;audit(t,'種目設定変更：'+reason);}
function regenerateInto(t:Tournament,sid:string,reason:string,ack=false){const s=t.stages.find(s=>s.id===sid);ensure(s,'ステージなし');ensure(!s.locked,'組合せ確定を解除してください');ensure(!stageDependents(t,sid).stages.length,'先に決勝を取消してください');const ms=t.matches.filter(m=>m.stageId===sid);ensure(!ms.some(m=>['called','playing'].includes(m.status)),'進行中は再生成できません');ensure(!ms.some(m=>m.status==='completed'||m.rubbers?.some(r=>r.games.length))||ack,'既存結果の保管・組合せ再生成への承認が必要です');const old=structuredClone(s);archive(t,[sid],reason);const next=draw(t,old.eventId,old.kind,old.groups.length,'seed',old.groups.flatMap(g=>g.entries),old.source,old.name);audit(t,'組合せ再生成：'+reason);return next;}
export function regenerate(t:Tournament,sid:string,reason:string,ack=false){validate(t);const draft=structuredClone(t),next=regenerateInto(draft,sid,reason,ack);validate(draft);Object.assign(t,draft);return t.stages.find(s=>s.id===next.id)!;}
function recordCorrectionInto(t:Tournament,id:string,reason:string,before:unknown,after:unknown){ensure(reason.trim(),'訂正理由を入力してください');(t.corrections??=[]).push({at:new Date().toISOString(),matchId:id,reason,before:structuredClone(before),after:structuredClone(after)});audit(t,'訂正：'+reason);}
function replaceEntryInto(t:Tournament,eid:string,entry:Entry,remove=false){const e=eventOf(t,eid);ensure(!t.stages.some(s=>s.eventId===eid),'組合せの保管・取消を先に実施してください');if(remove)e.entries=e.entries.filter(p=>p.id!==entry.id);else{const i=e.entries.findIndex(p=>p.id===entry.id);if(i>=0)e.entries[i]=entry;else e.entries.push(entry);}}

export function cancelFinals(t:Tournament,sid:string,reason:string,acknowledgedResults=false){return atomicMutation(t,d=>cancelFinalsInto(d,sid,reason,acknowledgedResults));}

export function archive(t:Tournament,sids:string[],reason:string){return atomicMutation(t,d=>archiveInto(d,sids,reason));}

export function adjudicate(t:Tournament,gid:string,order:string[],reason:string){return atomicMutation(t,d=>adjudicateInto(d,gid,order,reason));}

export function revokeRuling(t:Tournament,gid:string,reason:string){return atomicMutation(t,d=>revokeRulingInto(d,gid,reason));}

export function updateEvent(t:Tournament,eid:string,patch:Partial<Pick<Event,'name'|'type'|'rule'|'team'>>,reason:string){return atomicMutation(t,d=>updateEventInto(d,eid,patch,reason));}

export function recordCorrection(t:Tournament,id:string,reason:string,before:unknown,after:unknown){return atomicMutation(t,d=>recordCorrectionInto(d,id,reason,before,after));}

export function replaceEntry(t:Tournament,eid:string,entry:Entry,remove=false){return atomicMutation(t,d=>replaceEntryInto(d,eid,entry,remove));}
