import {atomicMutation} from './atomic.js';
import {ensure,entryOf,finished} from './model.js';import type {Tournament} from './model.js';import {numberBracket,propagate} from './engine.js';import {audit,stageDependents} from './governance.js';
function lockDrawInto(t:Tournament,sid:string,locked:boolean,reason:string){const s=t.stages.find(s=>s.id===sid);ensure(s&&reason.trim(),'ステージ・理由が必要です');s.locked=locked;audit(t,(locked?'組合せ確定：':'組合せ解除：')+reason);}
export function bracketSlots(t:Tournament,sid:string,gid?:string){return t.matches.filter(m=>m.stageId===sid&&(!gid||m.groupId===gid)&&m.round===1).flatMap(m=>[m.left,m.right]);}
function editBracketInto(t:Tournament,sid:string,slots:string[],reason:string,gid?:string){const s=t.stages.find(s=>s.id===sid);ensure(s&&s.kind==='bracket'&&!s.locked,'未確定トーナメントを選択してください');const group=gid?s.groups.find(g=>g.id===gid):s.groups.length===1?s.groups[0]:undefined;ensure(group,'編集する予選組を選択してください');ensure(reason.trim(),'変更理由が必要です');ensure(!stageDependents(t,sid).stages.length&&!t.matches.some(m=>m.stageId===sid&&(m.status==='completed'||['called','playing'].includes(m.status)||m.rubbers?.some(r=>r.games.length))),'結果・進行を保護しています。先に取消してください');const first=t.matches.filter(m=>m.stageId===sid&&m.groupId===group.id&&m.round===1);ensure(slots.length===first.length*2,'枠数が不一致');const members=group.entries;ensure(slots.filter(Boolean).length===members.length&&new Set(slots.filter(Boolean)).size===members.length&&slots.every(id=>!id||members.includes(id)),'全参加者を重複なく配置してください');ensure(first.every((_,i)=>slots[i*2]||slots[i*2+1]),'両側空枠の初戦は作れません');for(const m of t.matches.filter(m=>m.stageId===sid&&m.groupId===group.id)){m.status='waiting';m.winner='';m.games=[];m.walkover=false;m.rubbers=undefined;if(m.round>1){m.left='';m.right='';}}first.forEach((m,i)=>{m.left=slots[i*2];m.right=slots[i*2+1];});const stageMatches=t.matches.filter(m=>m.stageId===sid);const indexed=stageMatches.some(m=>m.bracketNo!==undefined);
 const originalPlayed=stageMatches.filter(m=>m.bracketNo!==undefined).map(m=>m.id);
 propagate(t,sid);
 if(indexed){
   const changed=stageMatches.some(m=>(m.status!=='bye')!==originalPlayed.includes(m.id));
   ensure(!changed||!stageMatches.some(m=>m.court||m.displayNumber),'採番済み・割当済みの初戦免除位置は変更できません');
   numberBracket(t,sid);
 }
 audit(t,'トーナメント枠変更：'+reason);}
function avoidClubsInto(t:Tournament,sid:string){const slots=bracketSlots(t,sid),conflicts=()=>slots.reduce((n,id,i)=>n+(i%2===0&&id&&slots[i+1]&&entryOf(t,id)!.club&&entryOf(t,id)!.club===entryOf(t,slots[i+1])!.club?1:0),0);const seed=(id:string)=>id?(entryOf(t,id)!.seed||999999):999999;let best=conflicts();for(let tries=0;tries<slots.length&&best;tries++){let changed=false;for(let i=0;i<slots.length;i++)for(let j=i+1;j<slots.length;j++){if((t.stages.find(s=>s.id===sid)?.rankDraw&&[slots[i],slots[j]].some(id=>id&&entryOf(t,id)?.rank!==undefined))||Math.floor(i/2)===Math.floor(j/2)||seed(slots[i])<999999||seed(slots[j])<999999)continue;[slots[i],slots[j]]=[slots[j],slots[i]];const n=conflicts(),valid=slots.every((id,k)=>k%2||id||slots[k+1]);if(valid&&n<best){best=n;changed=true;}else [slots[i],slots[j]]=[slots[j],slots[i]];}if(!changed)break;}editBracket(t,sid,slots,'同所属初戦回避（シード固定）');const s=t.stages.find(s=>s.id===sid)!;s.warnings=best?[`同所属の初戦が${best}試合残ります。人数構成または固定シード位置のため、この探索では回避できません。手動調整で確認してください。`]:[];return s.warnings;}

export function lockDraw(t:Tournament,sid:string,locked:boolean,reason:string){return atomicMutation(t,d=>lockDrawInto(d,sid,locked,reason));}

export function editBracket(t:Tournament,sid:string,slots:string[],reason:string,gid?:string){return atomicMutation(t,d=>editBracketInto(d,sid,slots,reason,gid));}

export function avoidClubs(t:Tournament,sid:string){return atomicMutation(t,d=>avoidClubsInto(d,sid));}

export function redrawUnranked(t:Tournament,sid:string,random=Math.random){
  return atomicMutation(t,d=>{
    const s=d.stages.find(s=>s.id===sid);
    ensure(s?.rankDraw,'ランク優先方式で生成した組合せを選択してください');
    ensure(!d.matches.some(m=>m.stageId===sid&&(m.court||m.startedAt!==undefined)),'割当・開始済みの組合せは再抽選できません');
    for(const g of s.groups){
      const slots=bracketSlots(d,sid,g.id);
      const at=slots.flatMap((id,i)=>id&&entryOf(d,id)?.rank===undefined?[i]:[]);
      const values=at.map(i=>slots[i]);
      for(let i=values.length-1;i>0;i--){
        const j=Math.floor(random()*(i+1));
        [values[i],values[j]]=[values[j],values[i]];
      }
      at.forEach((i,k)=>slots[i]=values[k]);
      editBracketInto(d,sid,slots,'未入力ランクだけ再抽選',g.id);
    }
  });
}
