import {ensure,uid} from './model.js';import type {MasterPlayer,Tournament} from './model.js';import {Store} from './storage.js';
export type Club={id:string;name:string;status:string};
export async function savePlayer(db:Store,p:MasterPlayer){ensure(/^[\w-]{1,100}$/.test(p.id)&&p.name.trim()&&p.name.length<=120&&['有効','休止'].includes(p.status),'選手マスター不正');await db.put('masters',{...p,kind:'player'});}
export async function saveClub(db:Store,c:Club){ensure(c.name.trim()&&c.id,'団体名が必要です');await db.put('masters',{...c,kind:'club'});}
export function registerMaster(t:Tournament,eid:string,player:MasterPlayer,clubName:string){const e=t.events.find(e=>e.id===eid);ensure(e&&e.type==='singles'&&!t.stages.some(s=>s.eventId===eid),'組合せ作成前のシングルス種目を選択してください');ensure(player.status==='有効'&&!e.entries.some(p=>p.players.includes(player.id)),'休止中または登録済みです');e.entries.push({id:uid(),name:player.name,club:clubName,players:[player.id],seed:0,kana:player.kana,gender:player.gender,grade:player.grade,status:player.status,reception:'未受付'});}
export function annualStats(tours:Tournament[],year:string){
 const unique=new Map<string,Tournament>();const fingerprint=(t:Tournament)=>JSON.stringify({matches:t.matches.map(m=>({id:m.id,left:m.left,right:m.right,winner:m.winner,games:m.games,rubbers:m.rubbers})).sort((a,b)=>a.id.localeCompare(b.id)),practice:t.practice});
 for(const t of tours.filter(t=>t.date.startsWith(year))){const prior=unique.get(t.origin);ensure(!prior||fingerprint(prior)===fingerprint(t),'同じ由来大会に異なる結果があります。集計対象の大会を一本化してください');if(!prior)unique.set(t.origin,t);}
 const rows=new Map<string,{id:string;name:string;played:number;wins:number;pointsFor:number;pointsAgainst:number;events:string[]}>();const get=(id:string,name:string)=>{if(!rows.has(id))rows.set(id,{id,name,played:0,wins:0,pointsFor:0,pointsAgainst:0,events:[]});return rows.get(id)!;};
 for(const t of unique.values()){const entries=new Map(t.events.flatMap(e=>e.entries).map(e=>[e.id,e]));const record=(id:string,name:string,win:boolean,games:[number,number][],left:boolean)=>{const r=get(id,name);r.played++;if(win)r.wins++;for(const g of games){r.pointsFor+=g[left?0:1];r.pointsAgainst+=g[left?1:0];}if(!r.events.includes(t.origin))r.events.push(t.origin);};
 for(const m of t.matches.filter(m=>m.status==='completed')){if(m.rubbers){for(const r of m.rubbers.filter(r=>r.winner))for(const side of ['left','right'] as const)for(const id of r[side])record(id,id,r.winner===side,r.games,side==='left');continue;}if(t.events.find(e=>e.id===m.eventId)?.type==='team')continue;for(const side of ['left','right'] as const){const p=entries.get(m[side]);if(p)for(const id of p.players)record(id,p.name,m.winner===m[side],m.games,side==='left');}}
 for(const p of t.practice||[])for(const m of p.matches.filter(m=>m.winner))for(const side of ['left','right'] as const)for(const id of m[side]){const member=p.members.find(m=>m.id===id);record(member?.masterId||id,member?.name||id,m.winner===side,m.games,side==='left');}
 }return [...rows.values()].sort((a,b)=>(b.played?b.wins/b.played:0)-(a.played?a.wins/a.played:0));
}
